NAME = 'FinSTLK2017: Pyhä Raamattu (STLK 2017)'
BOOK = 'Judges'

CHAPTERS = {
    1: {
        1: 'Joosuan kuoleman jälkeen israelilaiset kysyivät Herralta ja sanoivat: "Kenen meistä on lähdettävä ensiksi sotimaan kanaanilaisia vastaan?" Herra vastasi:',
        2: '"Juuda lähteköön. Katso, minä annan maan hänen käsiinsä."',
        3: 'Juuda sanoi veljelleen Simeonille: "Lähde kanssani arpaosaani. Sotikaamme kanaanilaisia vastaan, niin minäkin tulen kanssasi sinun arpaosaasi." Simeon lähti hänen kanssaan.',
        4: 'Juuda lähti. Herra antoi kanaanilaiset ja perissiläiset heidän käsiinsä. He voittivat heidät Besekissä – kymmenentuhatta miestä.',
        5: 'He kohtasivat Adoni-Besekin Besekissä ja taistelivat häntä vastaan ja voittivat kanaanilaiset ja perissiläiset.',
        6: 'Adoni-Besek pakeni, mutta he ajoivat häntä takaa ja ottivat hänet kiinni ja hakkasivat häneltä peukalot ja isotvarpaat.',
        7: 'Silloin Adoni-Besek sanoi: "Seitsemänkymmentä kuningasta, joilta oli hakattu peukalot ja isotvarpaat, kokosi muruja pöytäni alta. Niin kuin minä olen tehnyt, niin on Jumala minulle maksanut." He veivät hänet Jerusalemiin, ja siellä hän kuoli.',
        8: 'Juudan miehet ryhtyivät taisteluun Jerusalemia vastaan ja valloittivat sen ja surmasivat miekan terällä sen asukkaat ja pistivät kaupungin tuleen.',
        9: 'Sen jälkeen Juudan miehet laskeutuivat sotimaan niitä kanaanilaisia vastaan, jotka asuivat Vuoristossa, Negevissä ja Alankomaassa.',
        10: 'Juuda meni niitä kanaanilaisia vastaan, jotka asuivat Hebronissa – Hebronin nimi oli muinoin Kirjat-Arba – ja he voittivat Seesain, Ahimanin ja Talmain.',
        11: 'Sieltä hän meni Debirin asukkaita vastaan – Debirin nimi oli muinoin Kirjat-Seefer –',
        12: 'ja Kaaleb sanoi: "Joka voittaa ja valloittaa Kirjat-Seeferin, sille annan tyttäreni Aksan vaimoksi."',
        13: 'Niin Otniel, Kenaan, Kaalebin nuoremman veljen, poika, valloitti sen, ja hän [Kaaleb] antoi hänelle tyttärensä Aksan vaimoksi.',
        14: 'Kun Aksa tuli, hän yllytti miestään, että tämä pyytäisi hänen isältään peltomaata, ja Aksa pudottautui aasin selästä maahan. Silloin Kaaleb sanoi hänelle: "Mikä sinun on?"',
        15: 'Niin hän vastasi hänelle: "Anna minulle siunaus, sillä sinä olet antanut minut kuivaan maahan. Anna siis minulle vesilähteitä." Silloin Kaaleb antoi hänelle Ylälähteet ja Alalähteet.',
        16: 'Keeniläisen, Mooseksen apen, jälkeläiset olivat lähteneet Palmukaupungista Juudan jälkeläisten kanssa Juudan erämaahan, eteläpuolelle Aradia. He menivät ja asettuivat sikäläisen kansan sekaan.',
        17: 'Mutta Juuda meni veljensä Simeonin kanssa, ja he voittivat kanaanilaiset, jotka asuivat Sefatissa, ja he vihkivät kaupungin tuhon omaksi ja kutsuivat sen Hormaksi.',
        18: 'Juuda valloitti Gassan alueineen, Askelonin alueineen ja Ekronin alueineen.',
        19: 'Herra oli Juudan kanssa, niin että hän sai haltuunsa vuoriston. Hän ei näet kyennyt karkottamaan niitä, jotka asuivat tasangolla, koska heillä oli raudoitettuja sotavaunuja.',
        20: 'He antoivat Kaalebille Hebronin, niin kuin Mooses oli puhunut. Hän karkotti sieltä ne kolme anakilaista.',
        21: 'Mutta benjaminilaiset eivät karkottaneet jebusilaisia, jotka asuivat Jerusalemissa, ja jebusilaiset jäivät asumaan benjaminilaisten keskuuteen Jerusalemiin aina tähän päivään asti.',
        22: 'Myös Joosefin heimo lähti liikkeelle. Se lähti Beeteliin, ja Herra oli heidän kanssaan.',
        23: 'Joosefin heimo lähetti vakoilijoita Beeteliin – kaupungin nimi oli muinoin Luus –',
        24: 'ja vakoilijat näkivät miehen tulevan kaupungista ja sanoivat hänelle: "Näytä meille, mistä päästään kaupunkiin, niin teemme sinulle laupeuden."',
        25: 'Hän näytti heille, mistä päästiin kaupunkiin, ja he surmasivat miekan terällä kaupungin asukkaat, mutta miehen ja koko hänen sukunsa he päästivät menemään.',
        26: 'Mies meni heettiläisten maahan ja rakensi kaupungin ja antoi sille nimen Luus. Se nimi sillä on vielä tänäkin päivänä.',
        27: 'Mutta Manasse ei saanut haltuunsa Beet-Seania ja sen tytärkaupunkeja, ei Taanakia ja sen tytärkaupunkeja, ei Doorin asukkaita ja sen tytärkaupunkeja, ei Jibleamin asukkaita ja sen tytärkaupunkeja eikä Megiddon asukkaita ja sen tytärkaupunkeja, vaan kanaanilaisten onnistui jäädä asumaan maahan.',
        28: 'Kun Israel sitten voimistui, se saattoi kanaanilaiset työveron alaisiksi, mutta ei karkottanut heitä.',
        29: 'Efraim ei karkottanut kanaanilaisia, jotka asuivat Geserissä. Niin kanaanilaiset jäivät asumaan sen keskuuteen Geseriin.',
        30: 'Sebulon ei karkottanut Kidronin asukkaita eikä Nahalolin asukkaita. Kanaanilaiset jäivät asumaan sen keskuuteen, mutta joutuivat työveron alaisiksi.',
        31: 'Asser ei karkottanut Akkon asukkaita eikä Siidonin asukkaita eikä myöskään Ahlabin, Aksibin, Helban, Afekin ja Rehobin asukkaita.',
        32: 'Asserilaiset asuivat maan asukkaiden, kanaanilaisten, keskuudessa, koska eivät karkottaneet heitä.',
        33: 'Naftali ei karkottanut Beet-Semeksen asukkaita eikä Beet-Anatin asukkaita ja asui maan asukkaiden, kanaanilaisten, keskuudessa. Mutta Beet-Semeksen ja Beet-Anatin asukkaat olivat heille työveron alaisia.',
        34: 'Amorilaiset tunkivat daanilaiset vuoristoon, sillä he eivät sallineet heidän laskeutua tasangolle.',
        35: 'Amorilaisten onnistui jäädä asumaan Har-Herekseen, Aijaloniin ja Saalbimiin, mutta Joosefin heimon käsi kävi heille raskaaksi, ja he olivat työveron alaisia.',
        36: 'Amorilaisten alue ulottui Skorpionisolasta, Seelasta, ylöspäin.',
    },
    2: {
        1: 'Herran Enkeli tuli Gilgalista ylös Bookimiin. Hän sanoi: "Johdatin teidät Egyptistä ja toin teidät maahan, jonka valalla vannoen olin luvannut isillenne, ja sanoin: \'Minä en riko liittoani teidän kanssanne ikinä.',
        2: "Te taas älkää tehkö liittoa tämän maan asukasten kanssa, vaan kukistakaa heidän alttarinsa.' Mutta te ette ole kuulleet minun ääntäni. Mitä olettekaan tehneet!",
        3: 'Minäkin sanon nyt teille: Minä en karkota heitä tieltänne, vaan heistä tulee teille ahdistajia, ja heidän jumalansa tulevat teille ansaksi."',
        4: 'Kun Herran Enkeli oli puhunut nämä sanat kaikille israelilaisille, kansa korotti äänensä ja itki.',
        5: 'He antoivat paikalle nimen Bookim ja uhrasivat siinä Herralle.',
        6: 'Kun Joosua oli päästänyt kansan menemään, israelilaiset olivat menneet kukin perintöosalleen ottaakseen maan omakseen.',
        7: 'Kansa oli palvellut Herraa Joosuan koko elinajan ja niiden vanhinten koko elinajan, jotka elivät vielä kauan Joosuan jälkeen ja jotka olivat nähneet kaikki ne suuret teot, jotka Herra oli tehnyt Israelille.',
        8: 'Mutta Herran palvelija Joosua, Nuunin poika, oli kuollut sadan kymmenen vuoden vanhana.',
        9: 'He olivat haudanneet hänet hänen perintöosansa alueelle Timnat-Herekseen, Efraimin vuoristoon, Gaas-vuoren pohjoispuolelle.',
        10: 'Kun koko sekin sukupolvi oli tullut kootuksi isiensä luo, heidän jälkeensä nousi toinen sukupolvi, joka ei tuntenut Herraa eikä niitä tekoja, jotka hän oli tehnyt Israelille.',
        11: 'Israelilaiset tekivät sitä, mikä oli pahaa Herran silmissä, ja palvelivat baaleja',
        12: 'ja hylkäsivät Herran, isiensä Jumalan, joka oli vienyt heidät pois Egyptin maasta. He lähtivät kulkemaan muiden jumalien perässä, niiden kansojen jumalien, jotka asuivat heidän ympärillään, kumarsivat niitä ja vihoittivat Herran.',
        13: 'Mutta kun he hylkäsivät Herran ja palvelivat baalia ja astarteja,',
        14: 'Herran viha syttyi Israelia kohtaan, ja hän antoi heidät ryöstäjien käsiin, jotka ryöstivät heitä, ja myi heidät heidän ympärillään asuvien vihollisten käsiin, niin etteivät he enää voineet kestää vihollistensa edessä.',
        15: 'Mihin he lähtivätkin, Herran käsi oli heitä vastaan tuottaen onnettomuutta, niin kuin Herra oli puhunut ja niin kuin Herra oli heille vannonut. He joutuivat suureen ahdinkoon.',
        16: 'Silloin Herra herätti tuomareita, jotka pelastivat heidät heidän ryöstäjiensä käsistä.',
        17: 'Mutta he eivät totelleet tuomareitansakaan, vaan kulkivat haureudessa muiden jumalien jäljessä ja kumarsivat niitä. Pian he poikkesivat siltä tieltä, jota heidän isänsä Herran käskyjä totellen olivat kulkeneet eivätkä tehneet niin.',
        18: 'Kun siis Herra herätti heille tuomareita, niin Herra oli tuomarin kanssa ja pelasti heidät heidän vihollistensa käsistä niin kauaksi aikaa, kuin tuomari eli. Sillä Herran tuli sääli, kun he voihkivat sortajiensa ja ahdistajiensa käsissä.',
        19: 'Mutta kun tuomari kuoli, he vaelsivat jälleen kelvottomasti, vielä pahemmin kuin heidän isänsä, kulkien muiden jumalien perässä, palvellen ja kumartaen niitä. He eivät lakanneet teoistaan eivätkä paatuneesta vaelluksestaan.',
        20: 'Herran viha syttyi Israelia kohtaan, ja hän sanoi: "Koska tämä kansa on rikkonut liittoni, jonka minä säädin heidän isilleen, eivätkä he ole kuulleet ääntäni,',
        21: 'en minäkään enää karkota heidän tieltään ainoatakaan niistä kansoista, jotka Joosua kuollessaan jätti jäljelle.',
        22: 'Minä tahdon näin heissä koetella Israelia, noudattavatko he Herran tietä ja vaeltavatko sitä, niin kuin heidän isänsä tekivät, vai eivät."',
        23: 'Niin Herra jätti nämä kansat paikoilleen karkottamatta niitä heti. Hän ei ollut antanut niitä Joosuan käsiin.',
    },
    3: {
        1: 'Nämä ovat ne kansat, jotka Herra jätti paikoilleen koetellakseen niillä Israelia, kaikkia niitä, jotka eivät olleet kokeneet mitään mistään Kanaanin sodista –',
        2: 'hän jätti ne ainoastaan sitä varten, että israelilaisten sukupolvet saisivat kokea sotaa hänen opettaessaan heitä sotimaan, kuitenkin ainoastaan niitä, jotka eivät ennen olleet sotaa kokeneet –',
        3: 'filistealaisten viisi ruhtinasta ja kaikki kanaanilaiset ja siidonilaiset ja hivviläiset, jotka asuivat Libanonin vuoristossa, Baal-Hermonin vuoresta siihen saakka, mistä mennään Hamatiin.',
        4: 'Nämä jäivät, että hän niiden kautta koettelisi Israelia saadakseen tietää, tottelisivatko he Herran käskyjä, jotka hän oli antanut Mooseksen kautta heidän isilleen.',
        5: 'Israelilaiset asuivat siis kanaanilaisten, heettiläisten, amorilaisten, perissiläisten, hivviläisten ja jebusilaisten keskellä,',
        6: 'ja ottivat heidän tyttäriään vaimoikseen ja antoivat omia tyttäriään heidän pojilleen ja palvelivat heidän jumaliaan.',
        7: 'Israelilaiset tekivät sitä, mikä oli pahaa Herran silmissä, ja unohtivat Herran, Jumalansa, ja palvelivat baaleja ja aseroja.',
        8: 'Herran viha syttyi Israelia kohtaan, ja hän myi heidät Kuusan-Risataimin, Mesopotamian kuninkaan, käsiin. Israelilaiset palvelivat Kuusan-Risataimia kahdeksan vuotta.',
        9: 'Mutta israelilaiset huusivat Herraa, ja Herra herätti israelilaisille vapauttajan, joka heidät vapautti, Otnielin, Kenaan, Kaalebin nuoremman veljen, pojan.',
        10: 'Herran Henki tuli häneen, ja hän oli tuomarina Israelissa. Hän lähti sotaan, ja Herra antoi Kuusan-Risataimin, Aramin kuninkaan, hänen käsiinsä, ja Kuusan-Risataim sai tuntea hänen kätensä voiman.',
        11: 'Maassa oli rauha neljäkymmentä vuotta. Sitten Otniel, Kenaan poika, kuoli.',
        12: 'Mutta israelilaiset tekivät jälleen sitä, mikä oli pahaa Herran silmissä. Silloin Herra vahvisti Eglonin, Mooabin kuninkaan, Israelia väkevämmäksi, koska he tekivät sitä, mikä oli pahaa Herran silmissä.',
        13: 'Tämä kokosi luokseen ammonilaiset ja amalekilaiset, lähti liikkeelle ja voitti Israelin, ja he valtasivat Palmukaupungin.',
        14: 'Israelilaiset palvelivat Eglonia, mooabilaisten kuningasta, kahdeksantoista vuotta.',
        15: 'Israelilaiset huusivat Herraa, ja Herra herätti heille vapauttajan, benjaminilaisen Eehudin, Geeran pojan, vasenkätisen miehen. Kun israelilaiset lähettivät hänet viemään veroa Eglonille, Mooabin kuninkaalle,',
        16: 'niin Eehud teki itselleen kaksiteräisen miekan, jalan pituisen, ja sitoi sen takkinsa alle oikealle lanteelleen.',
        17: 'Hän toi veron Eglonille, Mooabin kuninkaalle. Mutta Eglon oli hyvin lihava mies.',
        18: 'Kun Eehud oli saanut tuoduksi veron, hän lähetti matkaan väen, joka oli kantanut verolahjoja.',
        19: 'Mutta hän itse kääntyi takaisin Gilgalin luona olevilta jumalankuvilta ja käski sanoa: "Minulla on salaista asiaa sinulle, kuningas." Niin tämä sanoi: "Hiljaa!" Silloin kaikki, jotka seisoivat hänen luonaan, poistuivat hänen luotaan.',
        20: 'Kun Eehud oli tullut hänen luokseen hänen istuessaan yksin viileässä yläsalissa, Eehud sanoi: "Minulla on sinulle sana Jumalalta." Silloin hän nousi istuimeltaan,',
        21: 'mutta Eehud ojensi vasemman kätensä ja tempasi miekan oikealta lanteeltaan ja pisti sen hänen vatsaansa,',
        22: 'niin että kahvakin meni sisään terän mukana ja terä upposi kokonaan ihraan, sillä hän ei vetänyt ulos miekkaa hänen vatsastaan. Sitten hän meni ulos laakealle katolle.',
        23: 'Kun Eehud oli tullut pylväskäytävään, hän sulki yläsalin ovet jälkeensä ja lukitsi ne.',
        24: 'Hänen mentyään tulivat kuninkaan palvelijat, ja kun he näkivät, että yläsalin ovet olivat lukitut, niin he ajattelivat: "Varmaankin hän on tarpeellaan viileässä kammiossa."',
        25: 'Sitten he odottivat kyllästymiseen asti, mutta kun hän ei sittenkään avannut yläsalin ovia, he ottivat avaimen ja avasivat itse. Niin, katso, heidän herransa makasi kuolleena lattialla.',
        26: 'Mutta Eehud oli paennut heidän vitkastellessaan. Hän oli jo päässyt jumalankuvien ohi ja pakeni Seiraan.',
        27: 'Sinne tultuaan hän puhalsi torveen Efraimin vuoristossa. Silloin israelilaiset laskeutuivat hänen kanssaan vuoristosta, ja hän heidän etunenässään.',
        28: 'Hän sanoi heille: "Seuratkaa minua, sillä Herra antaa vihollisenne, mooabilaiset, käsiinne." Silloin he laskeutuivat hänen jäljessään alas, valtasivat mooabilaisten tieltä Jordanin kahluupaikat eivätkä päästäneet ketään yli.',
        29: 'He voittivat silloin Mooabin, lähes kymmenen tuhatta miestä, kaikki voimakkaita ja sotakuntoisia miehiä, eikä ainoakaan päässyt pakoon.',
        30: 'Mooab nöyrtyi sinä päivänä Israelin käden alle. Maassa oli rauha kahdeksankymmentä vuotta.',
        31: 'Hänen jälkeensä tuli Samgar, Anatin poika. Hän surmasi filistealaisia kuusisataa miestä häränpistimellä. Hänkin vapautti Israelin.',
    },
    4: {
        1: 'Mutta Eehudin kuoltua israelilaiset tekivät jälleen sitä, mikä oli pahaa Herran silmissä.',
        2: 'Herra myi heidät Jaabinin, Kanaanin kuninkaan, käsiin, joka hallitsi Haasorissa. Hänen sotapäällikkönsä oli Siisera, joka asui Haroset-Goojimissa.',
        3: 'Israelilaiset huusivat Herraa, sillä Siiseralla oli yhdeksänsataa raudoitettua sotavaunua, ja hän sorti ankarasti israelilaisia kaksikymmentä vuotta.',
        4: 'Debora, naisprofeetta, Lappidotin vaimo, oli siihen aikaan tuomarina Israelissa.',
        5: 'Hänen oli tapana istua Debora-palmun alla, Raaman ja Beetelin välillä Efraimin vuoristossa, ja israelilaiset menivät hänen luokseen saamaan oikeutta.',
        6: 'Hän lähetti kutsumaan Baarakin, Abinoamin pojan, Naftalin Kedeksestä, ja sanoi hänelle: "Näin käskee Herra, Israelin Jumala: Lähde ja mene Taaborin vuorelle ja ota mukaasi kymmenentuhatta miestä naftalilaisia ja sebulonilaisia.',
        7: 'Minä tuon luoksesi Kiisonin purolle Siiseran, Jaabinin sotapäällikön, sotavaunuineen ja laumoineen ja annan hänet käsiisi."',
        8: 'Niin Baarak sanoi hänelle: "Jos sinä lähdet kanssani, niin minäkin lähden, mutta jos et lähde kanssani, niin en minäkään lähde."',
        9: 'Hän vastasi: "Lähden kanssasi, mutta kunnia siitä retkestä, jolle lähdet, ei tule sinulle, vaan Herra on myyvä Siiseran naisen käsiin." Debora nousi ja lähti Baarakin kanssa Kedekseen.',
        10: 'Baarak kutsui Sebulonin ja Naftalin koolle Kedekseen. Kymmenentuhatta miestä seurasi häntä, ja Debora lähti hänen kanssaan.',
        11: 'Mutta keeniläinen Heber oli eronnut keeniläisistä, Hoobabin, Mooseksen apen, jälkeläisistä. Hän oli telttaansa pystytellen tullut aina Saanaimin tammelle asti, joka on Kedeksen luona.',
        12: 'Kun Siiseralle ilmoitettiin, että Baarak, Abinoamin poika, oli noussut Taaborin vuorelle,',
        13: 'Siisera kutsui koolle kaikki sotavaununsa, yhdeksänsataa raudoitettua sotavaunua, ja kaiken väen, mikä hänellä oli, Haroset-Goojimista Kiisonin purolle.',
        14: 'Debora sanoi Baarakille: "Nouse, sillä tämä on se päivä, jona Herra antaa Siiseran käsiisi. Onhan Herra lähtenyt edelläsi." Baarak laskeutui Taaborin vuorelta, ja häntä seurasi kymmenentuhatta miestä.',
        15: 'Herra saattoi Baarakin miekan terän edessä sekasortoon Siiseran ja kaikki hänen sotavaununsa ja koko hänen joukkonsa. Siisera astui alas vaunuistaan ja pakeni jalkaisin.',
        16: 'Mutta Baarak ajoi takaa sotavaunuja ja sotajoukkoa Haroset-Goojimiin saakka. Koko Siiseran joukko kaatui miekan terään. Ainoakaan ei pelastunut.',
        17: 'Siisera oli paennut jalkaisin Jaaelin, keeniläisen Heberin vaimon, teltalle. Jaabinin, Haasorin kuninkaan, ja keeniläisen Heberin perheen välillä oli näet rauha.',
        18: 'Jaael meni Siiseraa vastaan ja sanoi hänelle: "Poikkea, herrani, poikkea luokseni, älä pelkää." Hän poikkesi hänen luokseen telttaan, ja hän peitti hänet peitteellä.',
        19: 'Hän sanoi hänelle: "Anna minulle vähän vettä juodakseni, sillä minun on jano." Niin hän avasi maitoleilin ja antoi hänen juoda ja peitti hänet.',
        20: 'Hän sanoi hänelle: "Asetu teltan ovelle. Jos joku tulee ja kysyy sinulta ja sanoo: \'Onko täällä ketään?\' vastaa: \'Ei ole.\'"',
        21: 'Mutta Jaael, Heberin vaimo, tempasi telttavaarnan, otti vasaran käteensä, hiipi hänen luokseen ja löi vaarnan hänen ohimoonsa, niin että se tunkeutui aina maahan asti. Hän oli näet väsymyksestä vaipunut sikeään uneen, ja hän kuoli.',
        22: 'Katso, silloin Baarak tuli ajaen Siiseraa takaa. Jaael meni häntä vastaan ja sanoi hänelle: "Tule, näytän sinulle miehen, jota etsit." Hän tuli hänen luokseen, ja katso, Siisera makasi kuolleena, vaarna ohimossaan.',
        23: 'Näin Jumala sinä päivänä nöyryytti Jaabinin, Kanaanin kuninkaan, israelilaisten edessä.',
        24: 'Israelilaisten käsi painoi yhä raskaammin Jaabinia, Kanaanin kuningasta, kunnes he tuhosivat Jaabinin, Kanaanin kuninkaan.',
    },
    5: {
        1: 'Sinä päivänä Debora ja Baarak, Abinoamin poika, lauloivat näin:',
        2: '"Johtajat johtivat Israelia, kansa oli altis. Kiittäkää Herraa.',
        3: 'Kuulkaa, te kuninkaat, kuunnelkaa, te ruhtinaat. Herran kiitosta minä laulan. Minä veisaan Herran, Israelin Jumalan, ylistystä.',
        4: 'Kun sinä, Herra, lähdit liikkeelle Seiristä, kun marssit Edomin maasta, maa järisi, ja taivaat vuotivat, pilvet vuotivat vettä.',
        5: 'Vuoret järkkyivät Herran edessä, itse Siinai Herran, Israelin Jumalan, edessä.',
        6: 'Samgarin, Anatin pojan, päivinä, Jaaelin päivinä tiet olivat tyhjät, matkamiehet kiertelivät syrjäisiä polkuja.',
        7: 'Israel oli johtoa vailla, peräti vailla, kunnes sinä, Debora, nousit, sinä, Israelin äiti.',
        8: 'He valitsivat uusia jumalia. Silloin oli sota porteilla asti, mutta ei näkynyt kilpeä, ei keihästä Israelin neljänkymmenen tuhannen joukossa.',
        9: 'Sydämeni on kiintynyt Israelin johtomiehiin. Te kansan joukossa alttiit, kiittäkää Herraa.',
        10: 'Te, jotka ratsastatte valkoisilla aasintammoilla, te, jotka istutte matoilla, ja te, jotka kuljette teillä, puhukaa.',
        11: 'Laulu kuuluu juotto-ojilta, siellä ylistetään Herran vanhurskaita tekoja, hänen johdatuksensa vanhurskautta Israelissa. Silloin Herran kansa laskeutui porteille.',
        12: 'Herää, herää, Debora! Herää, herää, laula laulu! Nouse, Baarak! Ota vankeja saaliiksesi, sinä Abinoamin poika!',
        13: 'Silloin pakolaiset laskeutuivat näiden jalojen luo. Herran kansa, sankarien joukko, laskeutui luokseni.',
        14: 'Efraimista tulivat ne, jotka saivat juurensa Amalekiin, he seurasivat joukkojesi mukana, Benjamin. Maakirista laskeutuivat johtomiehet, Sebulonista ne, jotka vetävät esiin kirjurin valtikan.',
        15: 'Isaskarin ruhtinaat tulivat Deboran kanssa, ja niin kuin Baarak, niin Isaskar: hän kiiti tasangolle hänen jäljessään. Ruubenin suvuissa oli suuria neuvotteluja.',
        16: 'Miksi jäit istumaan karjatarhojen välille, kuuntelemaan paimenpillin soittoa? Ruubenin suvuissa oli suuria neuvonpitoja.',
        17: 'Gilead pysyi alallaan tuolla puolella Jordanin, ja Daan – miksi hän viipyi vierailla laivoilla? Asser jäi istumaan meren rannalle ja pysyi alallaan lahtiensa luona.',
        18: 'Sebulon on kansa, joka antaa henkensä alttiiksi kuolemaan, samoin Naftali kedon kummuilla.',
        19: 'Kuninkaat tulivat ja taistelivat. Silloin taistelivat Kanaanin kuninkaat Taanakissa, Megiddon vesien varsilla. Mutta hopeaa he eivät saaneet saaliikseen.',
        20: 'Tähdet taivaalta kävivät sotaa. Radoiltaan ne sotivat Siiseraa vastaan.',
        21: 'Kiisonin puro tempasi heidät mukaansa, taistelujen puro, Kiisonin puro. Astu esiin, sieluni, voimassa!',
        22: 'Silloin hevoset tömistivät kavioillaan, kun he rynnistivät urhoollisia vastaan.',
        23: 'Kirotkaa Meeros, sanoo Herran Enkeli, kiroamalla kirotkaa sen asukkaat, koska eivät tulleet Herran avuksi, Herran avuksi sankarien joukkoon.',
        24: 'Siunattu olkoon vaimojen joukossa Jaael, keeniläisen Heberin vaimo, siunattu vaimojen joukossa, jotka teltoissa asuvat.',
        25: 'Vettä toinen pyysi, maitoa hän antoi, toi juhlamaljassa kokkelipiimää.',
        26: 'Hän ojensi kätensä ottamaan vaarnaa, oikean kätensä työvasaraa. Hän iski Siiseraa, löi murskaksi hänen päänsä, musersi ja lävisti hänen ohimonsa.',
        27: 'Hänen jalkojensa juureen hän vaipui, kaatui, jäi siihen, hänen jalkojensa juureen hän vaipui, kaatui, ja jäi kuolleena makaamaan siihen, mihin vaipui.',
        28: "Siiseran äiti katselee ikkunasta ja huutaa ristikon läpi: 'Miksi hänen sotavaunujensa tulo viipyy? Miksi hänen valjakkonsa askeleet ovat niin hitaat?'",
        29: 'Viisain hänen ruhtinattaristaan vastaa hänelle, ja hän kertaa itselleen hänen sanansa:',
        30: "'Varmaankin he ovat saaneet saalista ja jakavat sitä: tytön, kaksikin mieheen, kirjavaa kangasta saaliiksi Siiseralle, kirjavaa kangasta, kirjailtua vaatetta saaliiksi, kaksi kirjailtua, kirjavaa huivia saatujen saalisten kaulaan.'",
        31: 'Niin häviävät kaikki vihollisesi, Herra. Mutta ne, jotka häntä rakastavat, ovat kuin aurinko, kun se nousee voimassaan." Maassa oli rauha neljäkymmentä vuotta.',
    },
    6: {
        1: 'Mutta israelilaiset tekivät sitä, mikä oli pahaa Herran silmissä, ja Herra antoi heidät Midianin käsiin seitsemäksi vuodeksi.',
        2: 'Silloin Israel sai tuntea Midianin käden voiman, ja israelilaiset tekivät suojakseen midianilaisia vastaan ne onkalot, joita on vuorissa, ja luolat ja vuorilinnat.',
        3: 'Joka kerta kun israelilaiset olivat kylväneet, tulivat midianilaiset, amalekilaiset ja Idän miehet ja hyökkäsivät heidän kimppuunsa.',
        4: 'He leiriytyivät heitä vastaan ja hävittivät maan sadon aina Gassaa myöten eivätkä jättäneet mitään elintarpeita Israeliin, eivät myöskään lampaita, nautakarjaa eivätkä aaseja.',
        5: 'Sillä he lähtivät liikkeelle laumoineen ja telttoineen, he tulivat monilukuisina kuin heinäsirkat, heitä ja heidän kameleitaan oli lukematon määrä, ja he tulivat maahan hävittämään sitä.',
        6: 'Niin Israel joutui suureen kurjuuteen midianilaisten tähden, ja israelilaiset huusivat avuksi Herraa.',
        7: 'Kun israelilaiset huusivat Herraa Midianin tähden,',
        8: 'Herra lähetti israelilaisten luo profeetan, joka sanoi heille: "Näin sanoo Herra, Israelin Jumala: Minä johdatin teidät Egyptistä ja vein teidät pois orjuuden pesästä.',
        9: 'Pelastin teidät egyptiläisten käsistä ja kaikkien sortajienne käsistä. Karkotin heidät teidän tieltänne ja annoin teille heidän maansa.',
        10: 'Sanoin teille: Minä olen Herra, teidän Jumalanne, älkää pelätkö amorilaisten jumalia, joiden maassa asutte. Mutta ette kuulleet ääntäni."',
        11: 'Herran Enkeli tuli ja istui Ofran tammen alle, joka oli abieserilaisen Jooaan oma, juuri kun tämän poika Gideon oli puimassa vehnää viinikuurnassa korjatakseen ne talteen midianilaisilta.',
        12: 'Herran Enkeli ilmestyi hänelle ja sanoi hänelle: " Herra olkoon kanssasi, sinä väkevä sankari!"',
        13: 'Gideon vastasi hänelle: "Oi, Herrani, jos Herra on kanssamme, miksi sitten kaikki tämä on kohdannut meitä? Missä ovat kaikki hänen ihmetekonsa, joista isämme ovat meille kertoneet sanoen: \' Herra on johdattanut meidät tänne Egyptistä\'? Mutta nyt Herra on hylännyt meidät ja antanut meidät Midianin kouriin."',
        14: 'Silloin Herra kääntyi häneen ja sanoi: "Mene tässä voimassasi ja vapauta Israel Midianin kourista. Enkö ole sinua lähettänyt?"',
        15: 'Hän vastasi hänelle: "Oi, Herrani, millä minä vapautan Israelin? Sukunihan on heikoin Manassessa, ja minä olen kaikkein vähäpätöisin isäni perheessä."',
        16: 'Herra sanoi hänelle: "Olen kanssasi, ja [sinä] voitat midianilaiset kuin yhden miehen."',
        17: 'Mutta hän sanoi hänelle: "Jos olen saanut armon silmiesi edessä, osoita minulle tunnusteolla, että sinä itse puhut kanssani.',
        18: 'Älä poistu täältä, ennen kuin tulen takaisin luoksesi ja tuon uhrilahjani ja panen sen eteesi." Hän sanoi: "Minä jään, kunnes tulet takaisin."',
        19: 'Gideon meni ja valmisti kilin, ja eefa-mitan jauhoja happamattomiksi leiviksi, pani lihan koriin ja liemen pataan ja vei ne hänen luokseen tammen alle ja pani ne tarjolle.',
        20: 'Mutta Jumalan Enkeli sanoi hänelle: "Ota liha ja happamattomat leivät ja pane ne tälle kalliolle ja vuodata liemi." Hän teki niin.',
        21: 'Herran Enkeli ojensi sauvan, joka hänellä oli kädessään, ja kosketti sen kärjellä lihaa ja happamattomia leipiä. Kalliosta nousi tuli, ja se kulutti lihan ja happamattomat leivät. Sitten Herran Enkeli meni pois hänen silmistään.',
        22: 'Kun Gideon näki, että se oli ollut Herran Enkeli, Gideon sanoi: "Voi minua, Herra, Herra, kun olen nähnyt Herran Enkelin kasvoista kasvoihin!"',
        23: 'Mutta Herra sanoi hänelle: "Rauha sinulle! Älä pelkää, sinä et kuole."',
        24: 'Silloin Gideon rakensi siihen Herralle alttarin ja pani sen nimeksi: " Herra on rauha." Se on vielä tänäkin päivänä abieserilaisten Ofrassa.',
        25: 'Sinä yönä Herra sanoi hänelle: "Ota härkä, joka on isälläsi, ja toinen seitsenvuotias härkä ja hajota Baalin alttari, joka isälläsi on, ja hakkaa maahan aserapaalu, joka on sen vieressä.',
        26: 'Rakenna sitten ladotuista kivistä alttari Herralle, Jumalallesi, tämän vuorenkukkulan laelle. Ota sitten toinen härkä ja uhraa se polttouhriksi polttopuiden päällä, jotka saat hakkaamastasi aserapaalusta."',
        27: 'Gideon otti palvelijoitaan kymmenen miestä ja teki, niin kuin Herra oli hänelle puhunut. Mutta kun hän isänsä perhettä ja kaupungin miehiä peläten ei uskaltanut tehdä sitä päivällä, hän teki sen yöllä.',
        28: 'Kun kaupungin miehet varhain seuraavana aamuna nousivat, katso, Baalin alttari oli kukistettu ja aserapaalu oli sen vierestä hakattu maahan, ja toinen härkä oli uhrattu polttouhriksi vastarakennetulla alttarilla.',
        29: 'He sanoivat toinen toiselleen: "Kuka tämän on tehnyt?" Kun he tutkivat ja tiedustelivat, sanottiin: "Gideon, Jooaan poika, on sen tehnyt."',
        30: 'Silloin kaupungin miehet sanoivat Jooaalle: "Tuo tänne poikasi, hänen täytyy kuolla, sillä hän on tuhonnut Baalin alttarin ja hakannut maahan aserapaalun sen vierestä."',
        31: 'Mutta Jooas vastasi kaikille, jotka seisoivat hänen ympärillään: "Tekö ajatte Baalin asiaa, tekö autatte häntä? Se, joka ajaa hänen asiaansa, rangaistakoon kuolemalla ennen huomisaamua. Jos hän on jumala, ajakoon itse asiansa, koska kukistettu alttari oli hänen."',
        32: 'Sinä päivänä Gideon sai nimekseen Jerubbaal, sillä sanottiin: "Baal ajakoon itse asiansa häntä vastaan, koska hän on kukistanut hänen alttarinsa."',
        33: 'Kaikki midianilaiset, amalekilaiset ja Idän miehet olivat kokoontuneet yhteen, tulleet virran yli ja leiriytyneet Jisreelin tasangolle.',
        34: 'Herran Henki täytti Gideonin. Hän puhalsi torveen, ja abieserilaiset kutsuttiin koolle seuraamaan häntä.',
        35: 'Hän lähetti sanansaattajia koko Manasseen, niin että heidätkin kutsuttiin koolle seuraamaan häntä. Samoin hän lähetti sanansaattajat Asseriin, Sebuloniin ja Naftaliin, ja nämä lähtivät vihollisia vastaan.',
        36: 'Silloin Gideon sanoi Jumalalle: "Jos sinä aiot vapauttaa Israelin kädelläni, niin kuin olet puhunut,',
        37: 'katso, minä panen nämä kerityt villat puimatantereelle: jos kastetta tulee ainoastaan villoihin ja kaikki maa muuten jää kuivaksi, tiedän, että sinä vapautat kädelläni Israelin, niin kuin olet puhunut."',
        38: 'Tapahtui niin. Sillä kun hän varhain seuraavana päivänä nousi ja puristi villoja, pusersi hän kastetta villoista koko vesimaljan täyteen.',
        39: 'Gideon sanoi Jumalalle: "Älköön vihasi syttykö minua kohtaan, jos minä vielä kerran puhun. Anna minun tehdä vielä yksi koe villoilla. Anna ainoastaan villojen jäädä kuiviksi ja kastetta tulla kaikkialle muualle maahan."',
        40: 'Jumala teki niin sinä yönä. Ainoastaan villat jäivät kuiviksi, ja kastetta tuli kaikkialle muualle maahan.',
    },
    7: {
        1: 'Varhain seuraavana aamuna Jerubbaal, se on Gideon, sekä kaikki väki, joka oli hänen kanssaan, leiriytyi Harodin lähteelle. Midianilaisten leiri taas oli siitä, Mooren kukkulasta, pohjoiseen tasangolla.',
        2: 'Herra sanoi Gideonille: "Sinulla on kanssasi liian paljon väkeä antaakseni Midianin heidän käsiinsä. Muuten Israel voisi kerskua minua vastaan ja sanoa: \'Oma käteni vapautti minut.\'',
        3: 'Julista siis kansan kuullen näin: \'Se, joka pelkää ja on arka, palatkoon takaisin ja väistyköön Gileadin vuorilta.\'" Niin kansasta palasi takaisin kaksikymmentäkaksi tuhatta, ja kymmenentuhatta jäi.',
        4: 'Herra sanoi Gideonille: "Vielä on väkeä liian paljon. Vie heidät alas veden ääreen, niin minä tutkin heidät siellä sinulle. Se, josta minä sinulle sanon: \'Tämä lähteköön kanssasi\', se lähteköön kanssasi. Mutta kukaan, josta minä sinulle sanon: \'Tämä älköön lähtekö kanssasi\', älköön lähtekö."',
        5: 'Hän vei väen alas veden ääreen. Herra sanoi Gideonille: "Aseta erikseen jokainen, joka latkii vettä kielellään, niin kuin koira latkii, ja samoin jokainen, joka laskeutuu polvilleen juomaan."',
        6: 'Niiden luku, jotka latkivat kädestä suuhunsa, oli kolmesataa miestä. Kaikki muu väki oli laskeutunut polvilleen juomaan vettä.',
        7: 'Herra sanoi Gideonille: "Niillä kolmellasadalla miehellä, jotka latkivat, vapautan teidät ja annan Midianin käsiisi. Kaikki muu väki menköön kukin kotiinsa."',
        8: 'Sitten väki otti mukaansa eväät ja torvensa, ja hän päästi kaikki Israelin miehet menemään kunkin majalleen pitäen ainoastaan ne kolmesataa miestä. Midianilaisten leiri oli hänen alapuolellaan tasangolla.',
        9: 'Sinä yönä Herra sanoi hänelle: "Nouse ja käy leirin kimppuun, sillä minä annan sen sinun käsiisi.',
        10: 'Mutta jos sinä pelkäät käydä sen kimppuun, mene palvelijasi Puuran kanssa alas leiriin',
        11: 'ja kuuntele, mitä siellä puhutaan. Sitten saat rohkeutta käydä leirin kimppuun." Hän meni palvelijansa Puuran kanssa alas aina leirin etuvartijoiden luo.',
        12: 'Midianilaisia, amalekilaisia ja kaikkia Idän miehiä oli asettunut tasangolle paljon kuin heinäsirkkoja, eikä heidän kameleillaan ollut määrää, niitä oli niin paljon kuin hiekkaa meren rannalla.',
        13: 'Kun Gideon tuli, muuan mies kertoi untaan toiselle. Hän sanoi: "Minä näin unta ja katso, ohraleipäkakku tuli pyörien midianilaisten leiriin. Se tuli teltalle saakka, iski siihen niin, että se kaatui, ja käänsi sen ylösalaisin, ja teltta jäi kumoon."',
        14: 'Toinen vastasi ja sanoi: "Se ei ole mikään muu kuin israelilaisen Gideonin, Jooaan pojan, miekka. Jumala antaa hänen käsiinsä Midianin ja koko leirin."',
        15: 'Kun Gideon oli kuullut kertomuksen unesta ja sen selityksen, hän rukoili kumartaen, palasi sitten takaisin Israelin leiriin ja sanoi: "Nouskaa, sillä Herra antaa midianilaisten leirin käsiinne."',
        16: 'Hän jakoi ne kolmesataa miestä kolmeen joukkoon ja antoi heille kullekin käteen torven ja tyhjän saviruukun tulisoihdun ollessa ruukussa.',
        17: 'Hän sanoi heille: "Ottakaa minusta mallia ja tehkää kuten minä. Katso, kun minä olen tullut leirin laitaan, tehkää, kuten minä teen.',
        18: 'Kun minä ja kaikki, jotka ovat kanssani, puhallamme torviin, niin puhaltakaa tekin torviin kaikkialla leirin ympärillä ja huutakaa: \' Herran ja Gideonin puolesta!\'"',
        19: 'Niin Gideon ja ne sata miestä, jotka olivat hänen kanssaan, tulivat leirin laitaan keskimmäisen yövartion alussa. Vartijat olivat juuri asetetut paikoilleen. He puhalsivat torviin ja särkivät saviruukut, jotka heillä oli käsissään.',
        20: 'Ne kolme joukkoa puhalsivat torviin, murskasivat saviruukut, tempasivat vasempaan käteensä tulisoihdut ja oikeaan torvet, puhalsivat niihin ja huusivat: " Herran ja Gideonin miekka!"',
        21: 'He seisoivat kukin paikallaan leirin ympärillä. Mutta leirissä kaikki juoksivat sekaisin, huusivat ja pakenivat.',
        22: 'Kun he puhalsivat noihin kolmeensataan torveen, Herra käänsi toisen miekan toista vastaan koko leirissä, ja leiri pakeni Beet-Sittaan asti Sereraan päin, Tabbatin luona olevan Aabel-Meholan rantaan asti.',
        23: 'Sitten Israelin miehet kutsuttiin koolle Naftalista, Asserista ja koko Manassesta, ja he ajoivat midianilaisia takaa.',
        24: 'Gideon oli lähettänyt sanansaattajia koko Efraimin vuoristoon sanomaan: "Tulkaa alas midianilaisia vastaan ja vallatkaa heidän tieltään vedet aina Beet-Baaraan asti sekä Jordan." Kaikki Efraimin miehet kutsuttiin koolle, ja he valtasivat vedet aina Beet-Baaraan asti sekä Jordanin.',
        25: 'He ottivat vangiksi kaksi midianilaisten ruhtinasta, Oorebin ja Seebin. Oorebin he surmasivat Oorebin kalliolla, ja Seebin he surmasivat Seebin viinikuurnan luona, ja he ajoivat midianilaisia takaa. Oorebin ja Seebin päät he toivat Gideonille tuolta puolelta Jordanin.',
    },
    8: {
        1: 'Efraimin miehet sanoivat hänelle: "Miksi teit meille sen, ettet kutsunut meitä, kun lähdit taistelemaan midianilaisia vastaan?" He riitelivät kovasti häntä vastaan.',
        2: 'Niin hän sanoi heille: "Mitä olen nyt tehnyt teihin verraten? Eikö Efraimin jälkikorjuu ole parempi kuin Abieserin viininkorjuu?',
        3: 'Teidän käsiinnehän Jumala antoi midianilaisten ruhtinaat Oorebin ja Seebin. Mitä minä olen voinut tehdä teihin verraten?" Kun hän näin puhui, asettui heidän suuttumuksensa häneen.',
        4: 'Kun Gideon tuli Jordanille, hän meni sen yli, hän ja ne kolmesataa miestä, jotka olivat hänen kanssaan. He olivat uuvuksissa takaa-ajosta.',
        5: 'Hän sanoi Sukkotin miehille: "Antakaa joitakin leipäkakkuja väelle, joka seuraa minua, sillä he ovat uuvuksissa. Minä olen ajamassa takaa midianilaisten kuninkaita Sebahia ja Salmunnaa."',
        6: 'Mutta Sukkotin päämiehet sanoivat: "Onko sinulla sitten jo Sebahin ja Salmunnan nyrkki kädessäsi, että antaisimme leipää sotajoukollesi?"',
        7: 'Gideon vastasi: "Hyvä! Kun Herra antaa Sebahin ja Salmunnan käsiini, puin lihanne rikki erämaan orjantappuroilla ja orjanruoskilla."',
        8: 'Sitten hän kulki sieltä ylös Penueliin ja puhui heille samalla tavalla. Myös Penuelin miehet vastasivat hänelle samoin, kuin Sukkotin miehet olivat vastanneet.',
        9: 'Hän sanoi myös Penuelin miehille: "Kunhan palaan voittajana, kukistan tämän tornin."',
        10: 'Sebah ja Salmunna olivat Karkorissa ja heidän joukkonsa heidän kanssaan, noin viisitoista tuhatta miestä, kaikki, mitä oli jäljellä Idän miesten koko joukosta. Kaatuneita oli sata kaksikymmentä tuhatta miekkamiestä.',
        11: 'Gideon kulki teltoissa eläjien tietä Noobahin ja Jogbehan itäpuolitse ja voitti joukon, kun se oli huolettomana leirissään.',
        12: 'Sebah ja Salmunna pakenivat, mutta hän ajoi heitä takaa. Hän otti molemmat midianilaisten kuninkaat, Sebahin ja Salmunnan, vangiksi saatettuaan koko leirin pakokauhun valtaan.',
        13: 'Gideon, Jooaan poika, palasi taistelusta Hereksen solalta.',
        14: 'Hän otti kiinni erään nuorukaisen, joka oli Sukkotin miehiä, ja kyseli häneltä, ja tämä kirjoitti hänelle Sukkotin päämiehet ja vanhimmat, seitsemänkymmentä seitsemän miestä.',
        15: 'Kun hän sitten tuli Sukkotin miesten luo, hän sanoi: "Tässä ovat nyt Sebah ja Salmunna, joilla te pilkkasitte minua sanoen: \'Onko sinulla sitten jo Sebahin ja Salmunnan nyrkki kädessäsi, että antaisimme leipää uupuneille miehillesi?\'"',
        16: 'Hän otti kiinni kaupungin vanhimmat, otti sitten erämaan orjantappuroita ja orjanruoskia ja antoi Sukkotin miesten maistaa niitä.',
        17: 'Hän kukisti Penuelin tornin ja surmasi kaupungin miehet.',
        18: 'Sitten hän sanoi Sebahille ja Salmunnalle: "Minkä näköisiä ne miehet olivat, jotka tapoitte Taaborilla?" He vastasivat: "Ne olivat niin kuin sinä. Jokainen oli varreltaan kuin kuninkaan poika."',
        19: 'Hän sanoi: "He olivat veljiäni, äitini poikia. Niin totta kuin Herra elää: jos te olisitte jättäneet heidät henkiin, en surmaisi teitä."',
        20: 'Sitten hän sanoi Jeterille, esikoiselleen: "Nouse ja surmaa heidät." Mutta nuorukainen ei paljastanut miekkaansa, sillä hän pelkäsi, koska oli vielä nuori.',
        21: 'Silloin sanoivat Sebah ja Salmunna: "Nouse sinä ja pistä meidät kuoliaaksi, sillä miehellä on miehen voima." Gideon nousi ja surmasi Sebahin ja Salmunnan. Hän otti heidän kameliensa kaulasta puolikuukorut.',
        22: 'Niin Israelin miehet sanoivat Gideonille: "Hallitse sinä meitä, sekä sinä itse että poikasi ja poikasi poika. Olethan vapauttanut meidät Midianin käsistä."',
        23: 'Mutta Gideon vastasi heille: "En minä hallitse teitä, eikä poikani ole hallitseva teitä. Herra on teitä hallitseva."',
        24: 'Gideon sanoi heille: "Yhtä pyydän teiltä: antakoon kukin minulle heiltä saaliiksi saamansa nenärenkaan." Heikäläisillä näet on kultaiset nenärenkaat, koska ovat ismaelilaisia.',
        25: 'He vastasivat: "Annamme mielellämme." He levittivät viitan ja heittivät siihen kukin saaliiksi saamansa nenärenkaan.',
        26: 'Hänen pyytämänsä kultaiset nenärenkaat painoivat tuhat seitsemänsataa kultasekeliä lukuun ottamatta niitä puolikuukoruja, korvarenkaita ja purppuravaatteita, joita midianilaisten kuninkaat olivat kantaneet, ja heidän kameliensa kaulaketjuja.',
        27: 'Gideon valmisti niistä kasukan, jonka hän sijoitti kaupunkiinsa Ofraan, ja koko Israel kulki haureudessa siellä sen jäljessä. Se tuli ansaksi Gideonille ja hänen perheelleen.',
        28: 'Niin täytyi Midianin nöyrtyä israelilaisten edessä, eikä se enää nostanut päätään. Maassa oli rauha neljäkymmentä vuotta, niin kauan kuin Gideon eli.',
        29: 'Jerubbaal, Jooaan poika, meni ja jäi asumaan taloonsa.',
        30: 'Gideonilla oli seitsemänkymmentä poikaa, jotka olivat lähteneet hänen kupeistaan, sillä hänellä oli monta vaimoa.',
        31: 'Myös hänen sivuvaimonsa, joka hänellä oli Sikemissä, synnytti hänelle pojan, ja hän antoi tälle nimen Abimelek.',
        32: 'Gideon, Jooaan poika, kuoli päästyään korkeaan ikään, ja hänet haudattiin isänsä Jooaan hautaan abieserilaisten Ofraan.',
        33: 'Mutta kun Gideon oli kuollut, israelilaiset lähtivät haureudessa kulkemaan baalien jäljessä ja ottivat Baal-Beritin jumalakseen.',
        34: 'Eivätkä israelilaiset enää muistaneet Herraa, Jumalaansa, joka oli pelastanut heidät kaikkien heidän vihollistensa käsistä, jotka asuivat heidän ympärillään.',
        35: 'He eivät myöskään tehneet Jerubbaalin, Gideonin, perheelle laupeutta kaiken sen hyvän tähden, mitä hän oli tehnyt Israelille.',
    },
    9: {
        1: 'Abimelek, Jerubbaalin poika, meni Sikemiin äitinsä veljien luo ja puhui heille sekä kaikille, jotka olivat sukua hänen äitinsä isän perheelle, ja sanoi:',
        2: '"Puhukaa kaikkien Sikemin miesten kuullen: Kumpi teille on parempi, sekö, että teitä hallitsee seitsemänkymmentä miestä, kaikki Jerubbaalin pojat, vai että teitä hallitsee yksi mies? Muistakaa, että minä olen luutanne ja lihaanne."',
        3: 'Hänen äitinsä veljet puhuivat hänen puolestaan kaikkien Sikemin miesten kuullen kaiken tämän. Heidän sydämensä taipui Abimelekin puolelle, sillä he sanoivat: "Hän on veljemme."',
        4: 'He antoivat hänelle seitsemänkymmentä hopeasekeliä Baal-Beritin temppelistä. Niillä Abimelek palkkasi tyhjäntoimittajia ja huikentelijoita, ja ne seurasivat häntä.',
        5: 'Sitten hän lähti isänsä taloon Ofraan ja surmasi veljensä, Jerubbaalin pojat, seitsemänkymmentä miestä, saman kiven päällä. Mutta Jootam, Jerubbaalin nuorin poika, jäi henkiin, sillä hän oli mennyt piiloon.',
        6: 'Sen jälkeen kaikki Sikemin miehet ja koko Millon väki kokoontuivat, menivät ja tekivät Abimelekin kuninkaaksi Muistomerkkitammen luona, joka on Sikemissä.',
        7: 'Kun se kerrottiin Jootamille, hän meni, asettui seisomaan Garissimin vuoren laelle ja korotti äänensä, huusi ja sanoi heille: "Kuulkaa minua, te Sikemin miehet, että Jumalakin kuulisi teitä.',
        8: "Puut lähtivät voitelemaan itselleen kuningasta. He sanoivat öljypuulle: 'Ole sinä kuninkaamme.'",
        9: "Mutta öljypuu vastasi heille: 'Jättäisinkö lihavuuteni, josta jumalat ja ihmiset minua ylistävät, mennäkseni huojumaan ylempänä muita puita!'",
        10: "Puut sanoivat viikunapuulle: 'Tule sinä ja ole kuninkaamme.'",
        11: "Mutta viikunapuu vastasi heille: 'Jättäisinkö makeuteni ja hyvät hedelmäni mennäkseni huojumaan ylempänä muita puita!'",
        12: "Puut sanoivat viinipuulle: 'Tule sinä ja ole kuninkaamme.'",
        13: "Mutta viinipuu vastasi heille: 'Jättäisinkö rypälemehuni, joka saa jumalat ja ihmiset iloisiksi, mennäkseni huojumaan ylempänä muita puita!'",
        14: "Kaikki puut sanoivat orjantappuralle: 'Tule sinä ja ole kuninkaamme.'",
        15: "Orjantappura vastasi puille: 'Jos todella aiotte voidella minut kuninkaaksenne, tulkaa ja etsikää suojaa varjossani, mutta ellette, lähtee tuli orjantappurasta ja kuluttaa Libanonin setrit.'",
        16: 'Jos te nyt olette menetelleet uskollisesti ja rehellisesti tehdessänne Abimelekin kuninkaaksi ja jos olette kohdelleet hyvin Jerubbaalia ja hänen perhettään ja jos olette palkinneet häntä siitä, mitä hyvää hänen kätensä ovat tehneet –',
        17: 'sillä sotihan isäni teidän puolestanne ja pani alttiiksi henkensä ja pelasti teidät Midianin käsistä,',
        18: 'mutta te olette tänä päivänä nousseet isäni perhettä vastaan ja surmanneet hänen poikansa, seitsemänkymmentä miestä, saman kiven päällä ja tehneet Abimelekin, hänen orjattarensa pojan, Sikemin miesten kuninkaaksi, koska hän on teidän veljenne –',
        19: 'jos te siis olette tänä päivänä menetelleet uskollisesti ja rehellisesti Jerubbaalia ja hänen perhettään kohtaan, olkoon teillä iloa Abimelekista ja olkoon hänelläkin iloa teistä,',
        20: 'mutta ellette ole, lähteköön tuli Abimelekista ja kuluttakoon Sikemin miehet sekä Millon väen. Samoin lähteköön tuli Sikemin miehistä ja Millon väestä ja kuluttakoon Abimelekin."',
        21: 'Jootam lähti pakoon ja pääsi pakenemaan Beeriin. Hän asettui sinne suojaan veljeltään Abimelekilta.',
        22: 'Kun Abimelek oli hallinnut Israelia kolme vuotta,',
        23: 'Jumala lähetti pahan hengen Abimelekin ja Sikemin miesten väliin, niin että Sikemin miehet luopuivat Abimelekista,',
        24: 'jotta Jerubbaalin seitsemällekymmenelle pojalle tehty väkivalta tulisi kostetuksi ja heidän verensä tulisi Abimelekin, heidän veljensä, päälle, joka oli heidät surmannut, ja Sikemin miesten päälle, jotka olivat auttaneet häntä surmaamaan veljensä.',
        25: 'Sikemin miehet asettivat vuorten kukkuloille väijyjiä, ja nämä ryöstivät jokaisen, joka kulki sitä tietä heidän ohitseen. Se kerrottiin Abimelekille.',
        26: 'Mutta Gaal, Ebedin poika, tuli veljineen, ja he poikkesivat Sikemiin, ja Sikemin miehet luottivat häneen.',
        27: 'He menivät kedolle ja korjasivat sadon viinitarhoistaan, polkivat rypäleet ja pitivät ilojuhlan. He menivät jumalansa huoneeseen ja söivät, joivat ja kirosivat Abimelekia.',
        28: 'Gaal, Ebedin poika, sanoi: "Mikä on Abimelek, ja mikä on Sikem, että me häntä palvelisimme? Eikö hän ole Jerubbaalin poika, eikö Sebul ole hänen käskynhaltijansa? Palvelkaa Hamorin, Sikemin isän, miehiä. Miksi me palvelisimme häntä?',
        29: 'Olisipa minulla tuo kansa vallassani, minä toimittaisin pois Abimelekin. Mutta Abimelekista hän sanoi: \'Lisää sotajoukkoasi ja tule!\'"',
        30: 'Mutta kun Sebul, kaupungin päällikkö, kuuli Gaalin, Ebedin pojan, sanat, syttyi hänen vihansa.',
        31: 'Hän lähetti salaa sanansaattajia Abimelekin luo sanomaan: "Katso, Gaal, Ebedin poika, ja hänen veljensä ovat tulleet Sikemiin, ja nyt he yllyttävät kaupunkia sinua vastaan.',
        32: 'Nouse siis yöllä, sinä ja väki, joka on kanssasi, ja asetu kedolle väijyksiin.',
        33: 'Karkaa aamulla varhain, auringon noustessa, kaupungin kimppuun. Kun hän ja väki, joka on hänen kanssaan, lähtee silloin sinua vastaan, tee hänelle, minkä voit."',
        34: 'Silloin Abimelek ja kaikki väki, joka oli hänen kanssaan, lähti liikkeelle yöllä, ja he asettuivat väijyksiin Sikemiä vastaan neljässä joukossa.',
        35: 'Gaal, Ebedin poika, tuli ulos ja asettui kaupungin portin ovelle. Silloin Abimelek ja väki, joka oli hänen kanssaan, nousi väijyksistä.',
        36: 'Kun Gaal näki väen, hän sanoi Sebulille: "Katso, väkeä tulee alas vuorten kukkuloilta." Mutta Sebul vastasi hänelle: "Vuorten varjot näyttävät sinusta miehiltä."',
        37: 'Gaal puhui taas ja sanoi: "Katso, väkeä tulee alas Maan navalta, ja toinen joukko tulee Tietäjätammelta päin."',
        38: 'Sebul sanoi hänelle: "Missä on nyt sinun suuri suusi, kun sanoit: \'Mikä on Abimelek, että häntä palvelisimme?\' Siinä on nyt se väki, jota halveksit. Mene nyt ja taistele heitä vastaan."',
        39: 'Gaal lähti Sikemin miesten etunenässä ja taisteli Abimelekia vastaan.',
        40: 'Mutta Abimelek ajoi hänet pakoon, ja hän pääsi pakenemaan häntä. Heitä kaatui paljon, aina portin ovelle asti.',
        41: 'Abimelek jäi Arumaan, mutta Sebul karkotti Gaalin ja hänen veljensä pois Sikemistä.',
        42: 'Seuraavana päivänä kansa lähti ulos kedolle, ja siitä ilmoitettiin Abimelekille.',
        43: 'Hän otti väkensä ja jakoi sen kolmeen joukkoon ja asettui väijyksiin kedolle. Kun hän näki kansan lähtevän kaupungista, hän hyökkäsi heidän kimppuunsa ja surmasi heidät.',
        44: 'Abimelek ja ne joukot, jotka olivat hänen kanssaan, karkasivat näet esiin ja asettuivat kaupungin portin ovelle, samalla kun muut kaksi joukkoa kävivät kaikkien niiden kimppuun, jotka olivat kedolla, ja surmasivat heidät.',
        45: 'Abimelek taisteli kaupunkia vastaan koko sen päivän, valloitti kaupungin ja surmasi kansan, joka siellä oli. Hän hävitti kaupungin ja kylvi suolaa sen paikalle.',
        46: 'Kun kaikki Sikemin tornin miehet sen kuulivat, menivät he Eel-Beritin temppelin holviin.',
        47: 'Mutta kun Abimelekille kerrottiin, että kaikki Sikemin tornin miehet olivat kokoontuneet sinne,',
        48: 'Abimelek nousi Salmonin vuorelle, hän ja kaikki väki, joka oli hänen kanssaan. Abimelek otti kirveen käteensä ja löi poikki puunoksan, nosti ja pani sen olalleen ja sanoi väelle, joka oli hänen kanssaan: "Mitä näitte minun tekevän, tehkää tekin kiireesti."',
        49: 'Kukin väestäkin löi poikki oksansa, ja he seurasivat Abimelekia, panivat oksat holvin päälle ja sytyttivät holvin heidän päällään palamaan. Niin saivat surmansa myös kaikki Sikemin tornin asukkaat, noin tuhat miestä ja naista.',
        50: 'Sitten Abimelek meni Teebekseen, asettui leiriin Teebestä vastaan ja valloitti sen.',
        51: 'Mutta kaupungin keskellä oli luja torni, ja kaikki miehet ja naiset, kaikki kaupungin asukkaat, pakenivat sinne. He sulkivat oven jälkeensä ja nousivat tornin katolle.',
        52: 'Abimelek tuli tornin luo ja ryhtyi taisteluun sitä vastaan, ja hän astui tornin ovelle polttaakseen sen tulella.',
        53: 'Mutta eräs nainen heitti jauhinkiven Abimelekin päähän ja murskasi hänen pääkallonsa.',
        54: 'Silloin hän heti huusi palvelijalle, joka kantoi hänen aseitaan, ja sanoi hänelle: "Paljasta miekkasi ja surmaa minut, ettei minusta sanottaisi: \'Nainen tappoi hänet.\'" Hänen palvelijansa lävisti hänet, ja hän kuoli.',
        55: 'Kun Israelin miehet näkivät, että Abimelek oli kuollut, he menivät kukin kotiinsa.',
        56: 'Näin Jumala kosti Abimelekille sen pahan, minkä tämä oli tehnyt isäänsä kohtaan surmatessaan seitsemänkymmentä veljeään.',
        57: 'Jumala käänsi kaiken Sikemin miesten tekemän pahan heidän omaan päähänsä, ja heidät saavutti Jootamin, Jerubbaalin pojan, kirous.',
    },
    10: {
        1: 'Abimelekin jälkeen nousi Israelia vapauttamaan isaskarilainen Toola, Doodon pojan Puuan poika, joka asui Saamirissa, Efraimin vuoristossa.',
        2: 'Hän oli tuomarina Israelissa kaksikymmentä kolme vuotta. Sitten hän kuoli, ja hänet haudattiin Saamiriin.',
        3: 'Hänen jälkeensä nousi gileadilainen Jaair. Hän oli tuomarina Israelissa kaksikymmentä kaksi vuotta.',
        4: 'Hänellä oli kolmekymmentä poikaa, jotka ratsastivat kolmellakymmenellä aasilla. Heillä oli kolmekymmentä kaupunkia, joita vielä tänäkin päivänä kutsutaan Jaairin leirikyliksi ja jotka ovat Gileadin maassa.',
        5: 'Jaair kuoli, ja hänet haudattiin Kaamoniin.',
        6: 'Mutta israelilaiset tekivät jälleen sitä, mikä oli pahaa Herran silmissä. He palvelivat baaleja ja astarteja ja Aramin jumalia, Siidonin jumalia, Mooabin jumalia, ammonilaisten jumalia ja filistealaisten jumalia. He hylkäsivät Herran eivätkä palvelleet häntä.',
        7: 'Herran viha syttyi Israelia kohtaan, ja hän myi heidät filistealaisten ja ammonilaisten käsiin.',
        8: 'Nämä riistivät ja sortivat israelilaisia sen vuoden ja vielä kahdeksantoista vuotta, kaikkia israelilaisia, jotka asuivat Jordanin tuolla puolen amorilaisten maassa, Gileadissa.',
        9: 'Ammonilaiset menivät Jordanin yli taistelemaan myös Juudaa, Benjaminia ja Efraimin heimoa vastaan, ja niin Israel joutui suureen ahdinkoon.',
        10: 'Silloin israelilaiset huusivat Herraa sanoen: "Me olemme tehneet syntiä sinua vastaan, sillä me olemme hylänneet oman Jumalamme ja palvelleet baaleja."',
        11: 'Herra vastasi israelilaisille: "Eivätkö egyptiläiset, amorilaiset, ammonilaiset, filistealaiset,',
        12: 'siidonilaiset, amalekilaiset ja maaonilaiset sortaneet teitä, ja kun huusitte minua avuksi, enkö minä pelastanut teitä heidän käsistään?',
        13: 'Mutta te hylkäsitte minut ja palvelitte muita jumalia. Sen tähden en enää teitä pelasta.',
        14: 'Menkää ja huutakaa avuksenne niitä jumalia, jotka olette valinneet. Pelastakoot ne teidät ahdinkonne aikana."',
        15: 'Israelilaiset sanoivat Herralle: "Me olemme tehneet syntiä. Tee sinä meille aivan kuten hyväksi näet, kunhan vain tänä päivänä autat meitä."',
        16: 'He poistivat vieraat jumalat keskuudestaan ja palvelivat Herraa. Hän ei enää kärsinyt sitä, että Israelia vaivattiin.',
        17: 'Ammonilaiset kutsuttiin koolle, ja he leiriytyivät Gileadiin. Mutta israelilaiset kokoontuivat ja leiriytyivät Mispaan.',
        18: 'Silloin kansa, Gileadin ruhtinaat, sanoivat toisilleen: "Kuka on se mies, joka alkaa taistelun ammonilaisia vastaan? Hän on oleva kaikkien Gileadin asukkaiden päämies."',
    },
    11: {
        1: 'Gileadilainen Jefta oli väkevä sankari, mutta hän oli porton poika. Jeftan isä oli Gilead.',
        2: 'Mutta Gileadin vaimo oli synnyttänyt hänelle poikia, ja kun tämän vaimon pojat kasvoivat suuriksi, he karkottivat Jeftan ja sanoivat hänelle: "Et sinä saa perintöosaa isämme talossa, sillä sinä olet toisen naisen poika."',
        3: 'Jefta lähti pakoon veljiään ja asettui Toobin maahan. Jeftan luo kerääntyi tyhjäntoimittajia, ja he kuljeksivat yhdessä hänen kanssaan.',
        4: 'Jonkun ajan kuluttua ammonilaiset aloittivat sodan Israelia vastaan.',
        5: 'Kun nyt ammonilaiset aloittivat sodan Israelia vastaan, niin Gileadin vanhimmat lähtivät noutamaan Jeftaa Toobin maasta.',
        6: 'He sanoivat Jeftalle: "Tule ja ryhdy päälliköksemme sotiaksemme ammonilaisia vastaan."',
        7: 'Mutta Jefta vastasi Gileadin vanhimmille: "Ettekö te vihanneet minua ja karkottaneet minut isäni talosta? Miksi nyt, kun teillä on hätä, tulette luokseni?"',
        8: 'Gileadin vanhimmat sanoivat Jeftalle: "Juuri sen tähden olemme nyt kääntyneet puoleesi, ja jos sinä tulet kanssamme ja ryhdyt taistelemaan ammonilaisia vastaan, sinä olet oleva meidän, kaikkien Gileadin asukkaiden, päämies."',
        9: 'Jefta vastasi Gileadin vanhimmille: "Jos te viette minut takaisin taistelemaan ammonilaisia vastaan, ja Herra antaa heidät valtaani, minä tulen päämieheksenne."',
        10: 'Silloin Gileadin vanhimmat sanoivat Jeftalle: " Herra kuulee välipuheemme. Totisesti teemme kaiken, mitä sanoit."',
        11: 'Niin Jefta lähti Gileadin vanhinten kanssa, ja kansa asetti hänet päämiehekseen ja päällikökseen. Jefta lausui Herran edessä Mispassa kaiken, mitä oli puhunut.',
        12: 'Sitten Jefta lähetti ammonilaisten kuninkaan luo sanansaattajia sanomaan: "Mitä sinulla on kanssani tekemistä, kun tulet minua vastaan sotimaan maatani vastaan?"',
        13: 'Niin ammonilaisten kuningas vastasi Jeftan sanansaattajille: "Ottihan Israel tullessaan Egyptistä maani Arnonista Jabbokiin ja Jordaniin asti. Anna se nyt hyvällä takaisin."',
        14: 'Jefta lähetti taas sanansaattajia ammonilaisten kuninkaan luo',
        15: 'ja käski sanoa hänelle: "Näin sanoo Jefta: Israel ei ole ottanut Mooabin maata eikä ammonilaisten maata.',
        16: 'Sillä tullessaan Egyptistä Israel kulki erämaan kautta Kaislamerelle saakka ja tuli Kaadekseen.',
        17: "Israel lähetti sanansaattajia Edomin kuninkaan luo sanomaan: 'Salli minun kulkea maasi läpi.' Mutta Edomin kuningas ei kuullut heitä. He lähettivät sanan myös Mooabin kuninkaalle, mutta hänkään ei suostunut. Niin Israel asettui Kaadekseen.",
        18: 'Sitten he kulkivat erämaan kautta ja kiersivät Edomin maan ja Mooabin maan ja tulivat itäpuolelle Mooabin maata ja leiriytyivät Arnonin toiselle puolelle. He eivät tulleet Mooabin alueelle, sillä Arnon on Mooabin raja.',
        19: "Silloin Israel lähetti sanansaattajia Siihonin, amorilaisten kuninkaan, Hesbonin kuninkaan, luo, ja Israel käski sanoa hänelle: 'Salli meidän kulkea maasi läpi määräpaikkaamme.'",
        20: 'Mutta Siihon ei uskonut Israelia, että olisi sallinut sen kulkea alueensa läpi, vaan Siihon kokosi kaiken joukkonsa, ja he leiriytyivät Jahaaseen, ja hän ryhtyi taisteluun Israelia vastaan.',
        21: 'Mutta Herra, Israelin Jumala, antoi Siihonin ja kaiken hänen väkensä Israelin käsiin, niin että nämä voittivat heidät. Israel valloitti koko amorilaisten maan, niiden, jotka asuivat siinä maassa.',
        22: 'He ottivat omakseen koko amorilaisten alueen Arnonista Jabbokiin asti ja erämaasta Jordaniin saakka.',
        23: 'Näin siis Herra, Israelin Jumala, karkotti amorilaiset kansansa Israelin tieltä. Mutta nyt sinä ottaisit omaksesi heidän maansa!',
        24: 'Eikö ole niin: minkä jumalasi Kemos antaa omaksesi, sen sinä otat omaksesi, ja kenen hyvänsä Herra, meidän Jumalamme, karkottaa tieltämme, sen maan otamme omaksemme?',
        25: 'Vai oletko sinä parempi kuin Baalak, Sipporin poika, Mooabin kuningas? Rakensiko hän riitaa Israelin kanssa, tai ryhtyikö hän sotaan heitä vastaan?',
        26: 'Israel on nyt asunut Hesbonissa ja sen tytärkaupungeissa, Aroerissa ja sen tytärkaupungeissa ja kaikissa Arnonin varrella olevissa kaupungeissa kolmesataa vuotta. Miksi te ette sen ajan kuluessa ole ottaneet niitä pois?',
        27: 'Minä en ole rikkonut sinua vastaan, mutta sinä teet pahasti minua kohtaan, kun ryhdyt sotimaan minua vastaan. Herra, joka on tuomari, tuomitkoon tänä päivänä israelilaisten ja ammonilaisten välillä."',
        28: 'Mutta ammonilaisten kuningas ei ottanut kuullakseen, mitä Jefta lähetti hänelle sanomaan.',
        29: 'Herran Henki tuli Jeftaan, ja hän kulki Gileadin ja Manassen läpi ja kulki edelleen Gileadin Mispaan, ja Gileadin Mispasta hän lähti ammonilaisia vastaan.',
        30: 'Jefta teki lupauksen Herralle ja sanoi: "Jos annat ammonilaiset käsiini,',
        31: 'tulkoon kuka tulkoonkin minua vastaan taloni ovesta, kun voittajana palaan ammonilaisten luota, hän on oleva Herran, ja minä uhraan hänet polttouhriksi."',
        32: 'Jefta lähti ammonilaisia vastaan, sotimaan heitä vastaan, ja Herra antoi heidät hänen käsiinsä.',
        33: 'Hän tuotti heille hyvin suuren tappion, valloittaen maan Aroerista Minnitiin ja Aabel-Keramimiin asti, kaksikymmentä kaupunkia. Niin täytyi ammonilaisten nöyrtyä israelilaisten edessä.',
        34: 'Kun Jefta sitten tuli kotiinsa Mispaan, katso, hänen tyttärensä tuli ulos häntä vastaan tamburiinia lyöden ja karkeloiden. Hän oli hänen ainoa lapsensa. Tämän lisäksi hänellä ei ollut poikaa eikä tytärtä.',
        35: 'Nähdessään hänet hän repäisi vaatteensa ja sanoi: "Voi, tyttäreni, nyt sinä masennat minut maahan, nyt sinä syökset minut onnettomuuteen! Sillä minä avasin suuni Herralle enkä voi sanaani peruuttaa."',
        36: 'Hän vastasi hänelle: "Isäni, jos sinä avasit suusi Herralle, tee minulle, niin kuin suusi on puhunut, koska Herra on antanut sinun kostaa vihollisillesi, ammonilaisille."',
        37: 'Hän sanoi isälleen: "Myönnettäköön minulle kuitenkin tämä: jätä minut vapauteeni kahdeksi kuukaudeksi, että minä yhdessä ystävättärieni kanssa menen vuorille itkemään neitsyyttäni."',
        38: 'Niin hän sanoi: "Mene!" ja päästi hänet menemään kahdeksi kuukaudeksi. Hän meni ystävättärineen ja itki neitsyyttään vuorilla.',
        39: 'Mutta kahden kuukauden kuluttua hän palasi isänsä luo, ja tämä pani hänessä täytäntöön lupauksensa, jonka oli tehnyt. Eikä hän miehestä tietänyt. Tuli tavaksi Israelissa,',
        40: 'että Israelin tyttäret joka vuosi menivät lauluin ylistämään gileadilaisen Jeftan tytärtä – neljän päivän ajaksi joka vuosi.',
    },
    12: {
        1: 'Efraimin miehet kutsuttiin koolle, ja he lähtivät pohjoista kohti ja sanoivat Jeftalle: "Miksi lähdit sotimaan ammonilaisia vastaan kutsumatta meitä tulemaan kanssasi? Poltamme tulella talosi pääsi päältä."',
        2: 'Jefta vastasi heille: "Minulla ja kansallani oli kova taistelu ammonilaisten kanssa. Silloin kutsuin teitä, mutta te ette tulleet auttamaan minua heidän käsistään.',
        3: 'Kun näin, ettette te tulleet auttamaan minua, panin henkeni kämmenelleni ja lähdin ammonilaisia vastaan, ja Herra antoi heidät käsiini. Miksi te nyt olette lähteneet minua vastaan, sotimaan minua vastaan?"',
        4: 'Jefta kokosi kaikki Gileadin miehet ja ryhtyi taisteluun Efraimia vastaan. Gileadin miehet voittivat efraimilaiset, jotka olivat sanoneet: "Te olette karkureita Efraimista. Gilead on Efraimin ja Manassen keskuudessa."',
        5: 'Gileadilaiset valtasivat efraimilaisten tieltä Jordanin kahluupaikat. Kun sitten Efraimin pakolaiset sanoivat: "Antakaa minun mennä yli", Gileadin miehet kysyivät heiltä jokaiselta: "Oletko efraimilainen?" Jos hän vastasi: "En",',
        6: 'niin he sanoivat hänelle: "Sano \'šibbolet.\'" Jos hän sanoi "sibbolet", kun ei osannut ääntää oikein, ottivat he hänet kiinni ja tappoivat Jordanin kahluupaikoilla. Niin kaatui silloin Efraimista neljäkymmentä kaksi tuhatta.',
        7: 'Jefta oli tuomarina Israelissa kuusi vuotta. Sitten gileadilainen Jefta kuoli, ja hänet haudattiin erääseen Gileadin kaupunkiin.',
        8: 'Hänen jälkeensä oli Ibsan, Beetlehemistä, tuomarina Israelissa.',
        9: 'Hänellä oli kolmekymmentä poikaa, ja hän naitti kolmekymmentä tytärtään muualle ja toi muualta kolmekymmentä tyttöä pojilleen vaimoiksi. Hän oli tuomarina Israelissa seitsemän vuotta.',
        10: 'Sitten Ibsan kuoli, ja hänet haudattiin Beetlehemiin.',
        11: 'Hänen jälkeensä oli sebulonilainen Eelon tuomarina Israelissa. Hän oli tuomarina Israelissa kymmenen vuotta.',
        12: 'Sitten sebulonilainen Eelon kuoli, ja hänet haudattiin Aijaloniin, Sebulonin maahan.',
        13: 'Hänen jälkeensä oli piratonilainen Abdon, Hillelin poika, tuomarina Israelissa.',
        14: 'Hänellä oli neljäkymmentä poikaa ja kolmekymmentä pojanpoikaa, jotka ratsastivat seitsemälläkymmenellä aasilla. Hän oli tuomarina Israelissa kahdeksan vuotta.',
        15: 'Sitten piratonilainen Abdon, Hillelin poika, kuoli, ja hänet haudattiin Piratoniin, Efraimin maahan, amalekilaisten vuoristoon.',
    },
    13: {
        1: 'Kun israelilaiset yhä tekivät sitä, mikä oli pahaa Herran silmissä, Herra antoi heidät filistealaisten käsiin neljäksikymmeneksi vuodeksi.',
        2: 'Sorassa oli mies, Daanin sukukuntaa, nimeltä Maanoah. Hänen vaimonsa oli hedelmätön eikä ollut synnyttänyt.',
        3: 'Silloin Herran Enkeli ilmestyi vaimolle ja sanoi hänelle: "Katso, sinä olet hedelmätön etkä ole synnyttänyt, mutta sinä tulet raskaaksi ja synnytät pojan.',
        4: 'Varo siis, ettet juo viiniä ja väkijuomaa etkä syö mitään saastaista.',
        5: 'Sillä katso, sinä tulet raskaaksi ja synnytät pojan. Partaveitsi älköön koskettako hänen päätään, sillä poika on oleva Jumalan nasiiri äitinsä kohdusta asti, ja hän on aloittava Israelin vapauttamisen filistealaisten käsistä."',
        6: 'Vaimo lähti ja sanoi miehelleen näin: "Jumalan mies tuli luokseni. Hän oli näöltään kuin Jumalan Enkeli, hyvin pelottava. En kysynyt häneltä, mistä hän oli, eikä hän ilmaissut minulle nimeään.',
        7: 'Hän sanoi minulle: \'Katso, sinä tulet raskaaksi ja synnytät pojan. Älä siis juo viiniä ja väkijuomaa äläkä syö mitään saastaista, sillä poika on oleva Jumalan nasiiri äitinsä kohdusta aina kuolinpäiväänsä asti.\'"',
        8: 'Silloin Maanoah rukoili Herraa ja sanoi: "Oi Herra, salli Jumalan miehen, jonka lähetit, vielä tulla luoksemme opettamaan meille, mitä meidän on tehtävä pojalle, joka on syntyvä."',
        9: 'Jumala kuuli Maanoahin rukouksen, ja Jumalan Enkeli tuli jälleen vaimon luo, kun tämä istui kedolla. Mutta Maanoah, hänen miehensä, ei ollut hänen kanssaan.',
        10: 'Vaimo juoksi nopeasti ilmoittamaan miehelleen ja sanoi hänelle: "Katso, sama mies, joka äsken kävi luonani, ilmestyi minulle."',
        11: 'Niin Maanoah nousi ja seurasi vaimoaan. Kun hän tuli miehen luo, hän sanoi tälle: "Sinäkö olet se mies, joka puhuttelit tätä vaimoa?" Hän vastasi: "Minä."',
        12: 'Silloin Maanoah sanoi: "Kun sanasi käy toteen, miten sitten on meneteltävä pojan kanssa ja mitä hänelle on tehtävä?"',
        13: 'Herran Enkeli sanoi Maanoahille: "Varokoon vaimo kaikkea, mistä minä olen hänelle puhunut:',
        14: 'älköön syökö mitään, mikä viiniköynnöksestä tulee, viiniä ja väkijuomaa hän älköön juoko älköönkä syökö mitään saastaista. Noudattakoon kaikkea, mitä minä olen käskenyt hänen noudattaa."',
        15: 'Maanoah sanoi Herran Enkelille: "Salli meidän pidätellä sinua valmistaaksemme sinulle kilin."',
        16: 'Mutta Herran Enkeli vastasi Maanoahille: "Vaikka pidättelisitkin minua, en kuitenkaan söisi ruokaasi. Mutta jos tahdot valmistaa polttouhrin, uhraa se Herralle." Sillä Maanoah ei tiennyt häntä Herran Enkeliksi.',
        17: 'Maanoah sanoi Herran Enkelille: "Mikä on nimesi kunnioittaaksemme sinua, kun sinun sanasi käy toteen?"',
        18: 'Herran Enkeli vastasi hänelle: "Minkä tähden kysyt minun nimeäni? Se on Ihmeellinen."',
        19: 'Maanoah otti kilin ja ruokauhrin ja uhrasi sen kalliolla Herralle. Herra teki ihmeen Maanoahin ja hänen vaimonsa nähden:',
        20: 'liekin kohotessa alttarilta taivasta kohti kohosi Herran Enkeli alttarin liekissä ylös Maanoahin ja hänen vaimonsa nähden, ja he heittäytyivät kasvoilleen maahan,',
        21: 'eikä Herran Enkeli enää ilmestynyt Maanoahille ja hänen vaimolleen. Nyt Maanoah tiesi hänet Herran Enkeliksi.',
        22: 'Niin Maanoah sanoi vaimolleen: "Olemme kuoleman omat, sillä olemme nähneet Jumalan."',
        23: 'Mutta hänen vaimonsa vastasi hänelle: "Jos Herra tahtoisi surmata meidät, hän ei olisi ottanut meiltä vastaan polttouhria ja ruokauhria eikä antanut meidän nähdä tätä kaikkea eikä antanut meidän juuri nyt tätä kuulla."',
        24: 'Sen jälkeen vaimo synnytti pojan ja antoi hänelle nimen Simson, ja poika kasvoi, ja Herra siunasi häntä.',
        25: 'Herran Henki alkoi hänessä vaikuttaa Daanin leirissä Soran ja Estaolin välillä.',
    },
    14: {
        1: 'Simson meni alas Timnaan ja näki Timnassa naisen, filistealaisten tyttäriä.',
        2: 'Hän tuli sieltä ja kertoi sen isälleen ja äidilleen ja sanoi: "Minä näin Timnassa naisen, filistealaisten tyttäriä. Ottakaa hänet nyt minulle vaimoksi."',
        3: 'Hänen isänsä ja äitinsä sanoivat hänelle: "Eikö veljiesi tyttärien joukossa ja koko kansassani ole yhtään naista, kun aiot mennä ottamaan vaimon ympärileikkaamattomien filistealaisten joukosta?" Mutta Simson sanoi isälleen: "Ota hänet minulle, sillä hän on mieluinen silmissäni."',
        4: 'Mutta hänen isänsä ja äitinsä eivät tienneet, että se tuli Herralta, sillä hän etsi tilaisuutta filistealaisia vastaan. Filistealaiset näet hallitsivat siihen aikaan Israelia.',
        5: 'Simson meni isänsä ja äitinsä kanssa alas Timnaan. Mutta kun he saapuivat Timnan viinitarhoille, katso, nuori leijona tuli ärjyen häntä vastaan.',
        6: 'Silloin Herran Henki tuli häneen, niin että hän repäisi sen, niin kuin olisi reväissyt kilin, paljain käsin. Eikä hän ilmoittanut isälleen eikä äidilleen, mitä oli tehnyt.',
        7: 'Hän meni sinne ja puhutteli naista, ja tämä oli mieluinen Simsonin silmissä.',
        8: 'Kun hän jonkin ajan kuluttua palasi sinne ottaakseen hänet, hän poikkesi katsomaan leijonan raatoa, ja katso, leijonan ruumiissa oli mehiläisparvi ja hunajaa.',
        9: 'Hän kaapi hunajan kouriinsa ja kulki edelleen ja söi sitä. Hän tuli isänsä ja äitinsä luo ja antoi heille, ja he söivät. Mutta hän ei sanonut heille, että oli kaapinut hunajan leijonan ruumiista.',
        10: 'Hänen isänsä meni naisen luo, ja Simson laittoi siellä pidot, sillä niin oli nuorten miesten tapa.',
        11: 'Mutta kun he näkivät hänet, valitsivat he kolmekymmentä sulhaspoikaa olemaan hänen kanssaan.',
        12: 'Simson sanoi heille: "Minä panen teille arvoituksen. Jos selitätte sen minulle seitsemän pitopäivän kuluessa ja arvaatte oikein, annan teille kolmekymmentä pellavapaitaa ja kolmekymmentä juhlapukua.',
        13: 'Mutta ellette voi sitä minulle selittää, te annatte minulle kolmekymmentä pellavapaitaa ja kolmekymmentä juhlapukua." He sanoivat hänelle: "Lausu arvoituksesi, että saamme sen kuulla."',
        14: 'Hän sanoi heille: "Lähti syötävä syömäristä, lähti väkevästä makea." Mutta he eivät voineet kolmen päivän kuluessa selittää arvoitusta.',
        15: 'Seitsemäntenä päivänä he sanoivat Simsonin vaimolle: "Viekoittele miehesi selittämään meille arvoitus, muuten poltamme sinut ja sinun isäsi talon tulella. Oletteko kutsuneet meidät tänne köyhdyttääksenne meitä, vai kuinka?"',
        16: 'Simsonin vaimo ahdisti häntä itkullaan ja sanoi: "Sinähän vihaat minua etkä rakasta. Sinä olet pannut arvoituksen kansalaisilleni etkä selitä sitä minulle." Mutta hän vastasi hänelle: "En ole selittänyt sitä edes isälleni enkä äidilleni, sinulleko sen selittäisin!"',
        17: 'Hän ahdisti häntä itkullaan ne seitsemän päivää, jotka heidän pitonsa kestivät. Mutta seitsemäntenä päivänä Simson selitti hänelle, koska vaimo häntä ahdisti. Sen jälkeen vaimo selitti arvoituksen kansalaisilleen.',
        18: 'Kaupungin miehet sanoivat hänelle seitsemäntenä päivänä, ennen kuin aurinko laski: "Mikä on makeampaa kuin hunaja, ja mikä leijonaa väkevämpi?" Hän vastasi heille: "Ellette olisi kyntäneet vasikallani, ette olisi arvoitustani arvanneet."',
        19: 'Silloin Herran Henki tuli häneen, ja hän meni Askeloniin, löi siellä kuoliaaksi kolmekymmentä miestä, otti heiltä vaatteet ja antoi juhlapuvut arvoituksen selittäjille. Hänen vihansa syttyi, ja hän meni isänsä kotiin.',
        20: 'Mutta Simsonin vaimo tuli sille sulhaspojista, joka oli ollut yljän ystävänä.',
    },
    15: {
        1: 'Jonkin ajan kuluttua, vehnänleikkuuaikaan, tuli Simson katsomaan vaimoaan tuomisinaan kili, ja sanoi: "Minä menen vaimoni luo sisähuoneeseen." Mutta tämän isä ei sallinut hänen mennä,',
        2: 'vaan sanoi: "Minä tosiaankin luulin, että olit ruvennut vihaamaan häntä, ja annoin hänet sulhaspojallesi. Mutta onhan hänen nuorempi sisarensa häntä kauniimpi, saat hänet toisen sijaan."',
        3: 'Mutta Simson vastasi heille: "Nyt minä en tule syynalaiseksi filistealaisista, vaikka teenkin heille pahaa."',
        4: 'Simson meni ja pyydysti kolmesataa kettua. Hän otti tulisoihtuja, sitoi aina kaksi häntää yhteen ja asetti tulisoihdun kunkin häntäparin väliin.',
        5: 'Hän sytytti tulisoihdut ja päästi ketut menemään filistealaisten viljapeltoihin. Hän sytytti palamaan sekä kuhilaat että kasvavan viljan, viinitarhat ja öljypuut.',
        6: 'Filistealaiset kysyivät: "Kuka tämän on tehnyt?" Vastattiin: "Simson, timnalaisen vävy, koska tämä otti hänen vaimonsa ja antoi sen hänen sulhaspojalleen." Filistealaiset menivät ja polttivat sekä vaimon että hänen isänsä tulessa.',
        7: 'Mutta Simson sanoi heille: "Koska te näin teitte, totisesti lakkaan vasta sitten, kun olen kostanut."',
        8: 'Hän piiskasi heitä lanteisiin ja jalkoihin pahasti haavoittaen heitä. Hän meni ja asettui asumaan Eetamin kallioluolaan.',
        9: 'Filistealaiset lähtivät liikkeelle, leiriytyivät Juudaan ja levittäytyivät Lehin tienoille.',
        10: 'Juudan miehet kysyivät: "Miksi olette tulleet meitä vastaan?" He vastasivat: "Me olemme tulleet sitomaan Simsonin tehdäksemme hänelle, niin kuin hän teki meille."',
        11: 'Niin kolmetuhatta miestä Juudasta meni Eetamin kallioluolalle, ja he sanoivat Simsonille: "Etkö tiedä, että filistealaiset hallitsevat meitä? Mitä oletkaan meille tehnyt!" Hän vastasi heille: "Niin kuin he tekivät minulle, niin minäkin tein heille."',
        12: 'He sanoivat hänelle: "Tulimme sitomaan sinut antaaksemme sinut filistealaisten käsiin." Mutta Simson sanoi heille: "Vannokaa minulle, ettette itse lyö minua kuoliaaksi."',
        13: 'He vastasivat hänelle sanoen: "Emme lyö. Me vain sidomme sinut ja annamme sinut heidän käsiinsä, mutta emme sinua surmaa." He sitoivat hänet kahdella uudella köydellä ja veivät hänet pois kalliolta.',
        14: 'Kun hän saapui Lehiin, filistealaiset riensivät riemuhuudoin häntä vastaan. Silloin Herran Henki tuli häneen, ja samalla köydet hänen käsivarsissaan olivat kuin tulen polttamat pellavalangat, ja hänen siteensä sulivat pois hänen käsistään.',
        15: 'Hän huomasi tuoreen aasinleukaluun, ojensi kätensä, otti sen ja löi sillä kuoliaaksi tuhat miestä.',
        16: 'Simson sanoi: "Aasinleukaluulla minä löin heitä läjään, löin kahteen, aasinleukaluulla löin heitä tuhat miestä."',
        17: 'Sen sanottuaan hän heitti leukaluun kädestään. Sen paikan nimeksi tuli Raamat-Lehi.',
        18: 'Mutta kun hänellä oli kova jano, hän huusi Herraa ja sanoi: "Sinä annoit palvelijasi käden kautta tämän suuren voiton, mutta nyt kuolen janoon ja joudun ympärileikkaamattomien käsiin."',
        19: 'Jumala avasi syvänteen Lehiin, ja siitä vuoti vettä. Hän joi, ja hänen henkensä elpyi, ja hän virkistyi. Siitä lähde sai nimekseen Een-Hakkore. Se on vielä tänäkin päivänä Lehissä.',
        20: 'Hän oli filistealaisten aikana tuomarina Israelissa kaksikymmentä vuotta.',
    },
    16: {
        1: 'Niin Simson meni Gassaan ja näki siellä porton ja meni tämän luo.',
        2: 'Kun gassalaisille kerrottiin, että Simson oli tullut sinne, he piirittivät hänet ja väijyivät häntä koko yön kaupungin portilla. He olivat hiljaa koko yön ajatellen: "Kun aamu valkenee, surmaamme hänet."',
        3: 'Simson makasi siellä puoliyöhön asti. Mutta keskiyöllä hän nousi, tarttui kaupungin portin oviin ja molempiin pihtipieliin, nosti ne salpoineen paikaltaan, asetti hartioilleen ja vei ne sen vuoren laelle, joka on vastapäätä Hebronia.',
        4: 'Sen jälkeen hän rakastui erääseen Soorekin laaksossa asuvaan naiseen, jonka nimi oli Delila.',
        5: 'Filistealaisten ruhtinaat tulivat naisen luo ja sanoivat hänelle: "Viettele hänet ja ota selko, missä hänen suuri voimansa on ja miten voisimme voittaa hänet, että saisimme hänet sidotuksi ja masennetuksi, niin annamme sinulle kukin tuhat ja sata hopeasekeliä."',
        6: 'Silloin Delila sanoi Simsonille: "Ilmaise minulle, missä suuri voimasi on ja miten sinut voidaan sitoa ja lannistaa."',
        7: 'Simson vastasi hänelle: "Jos minut sidotaan seitsemällä tuoreella jänteellä, jotka eivät ole kuivuneet, tulen heikoksi ja olen kuin muutkin ihmiset."',
        8: 'Niin filistealaisten ruhtinaat toivat naiselle seitsemän tuoretta jännettä, jotka eivät olleet kuivuneet, ja hän sitoi hänet niillä.',
        9: 'Mutta sisähuoneessa hänellä istui väijyjiä. Niin hän sanoi hänelle: "Filistealaiset ovat kimpussasi, Simson!" Silloin tämä katkaisi jänteet, niin kuin katkeaa tulen kärventämä rohdinlanka. Ei siis päästy perille hänen voimastaan.',
        10: 'Delila sanoi Simsonille: "Katso, sinä olet pettänyt minut ja valehdellut minulle. Ilmaise nyt minulle, miten sinut voidaan sitoa."',
        11: 'Hän sanoi hänelle: "Jos minut sidotaan uusilla köysillä, joilla ei ole tehty työtä, tulen heikoksi ja olen kuin muutkin ihmiset."',
        12: 'Delila otti uudet köydet, sitoi hänet niillä ja sanoi hänelle: "Filistealaiset ovat kimpussasi, Simson!" Sisähuoneessa istui väijyjiä. Mutta hän katkaisi ne käsivarsistaan kuin langan.',
        13: 'Niin Delila sanoi Simsonille: "Sinä olet tähän asti minua pettänyt ja valehdellut minulle. Ilmaise minulle, miten sinut voidaan sitoa." Hän vastasi hänelle: "Jos kudot päässäni olevat seitsemän palmikkoa kankaan loimiin."',
        14: 'Niin Delila löi ne kiinni lujaan vaarnalla. Sitten hän sanoi hänelle: "Filistealaiset ovat kimpussasi, Simson!" Kun hän heräsi unestaan, hän repäisi irti vaarnan ja loimet.',
        15: 'Niin nainen sanoi hänelle: "Kuinka saatat sanoa: \'Rakastan sinua\', vaikka sydämesi ei ole kanssani? Jo kolme kertaa olet pettänyt minut etkä ole ilmaissut minulle, missä suuri voimasi on."',
        16: 'Kun hän joka päivä ahdisti häntä sanoillaan ja vaivasi häntä, hän tuskastui kuollakseen',
        17: 'ja paljasti hänelle koko sydämensä ja sanoi hänelle: "Ei ole partaveitsi päähäni koskenut, sillä minä olen Jumalan nasiiri äitini kohdusta asti. Jos minun hiukseni ajetaan, voimani lähtee minusta pois, ja tulen heikoksi ja olen kuin kaikki muutkin ihmiset."',
        18: 'Kun Delila huomasi, että hän oli paljastanut hänelle koko sydämensä, hän lähetti kutsumaan filistealaisten ruhtinaat sanoen: "Nyt tulkaa, sillä hän on paljastanut minulle koko sydämensä." Niin filistealaisten ruhtinaat tulivat hänen luokseen tuoden mukanaan rahat.',
        19: 'Sitten hän nukutti hänet polvilleen ja kutsui miehen, joka leikkasi hänen päänsä seitsemän palmikkoa. Hän alkoi saada hänet lannistetuksi, ja hänen voimansa poistui hänestä.',
        20: 'Delila sanoi: "Filistealaiset ovat kimpussasi, Simson!" Kun hän heräsi unestaan, hän ajatteli: "Kyllä minä selviydyn niin kuin aina ennenkin ja ravistan itseni vapaaksi." Eikä hän tiennyt, että Herra oli poistunut hänestä.',
        21: 'Filistealaiset ottivat hänet kiinni ja puhkaisivat hänen silmänsä. He veivät hänet Gassaan ja sitoivat hänet vaskikahleisiin, ja hänen täytyi jauhaa vankilassa.',
        22: 'Mutta hiukset rupesivat jälleen kasvamaan hänen päähänsä sen jälkeen, kun ne olivat ajetut.',
        23: 'Filistealaisten ruhtinaat kokoontuivat uhraamaan suurta uhria jumalalleen Daagonille ja iloa pitämään, sillä he sanoivat: "Jumalamme on antanut vihollisemme Simsonin käsiimme."',
        24: 'Kun kansa näki hänet, he ylistivät jumalaansa, sillä he sanoivat: "Jumalamme on antanut käsiimme vihollisemme, maamme hävittäjän, sen, joka surmasi meistä niin monta."',
        25: 'Kun heidän sydämensä olivat tulleet iloisiksi, he sanoivat: "Noutakaa Simson huvittamaan meitä." Simson noudettiin vankilasta huvittamaan heitä. He asettivat hänet seisomaan pylväiden väliin.',
        26: 'Simson sanoi palvelijalle, joka piti kiinni hänen kädestään: "Päästä minut tunnustelemaan pylväitä, joiden varassa rakennus on, nojatakseni niihin."',
        27: 'Mutta huone oli täynnä miehiä ja naisia, myös kaikki filistealaisten ruhtinaat olivat siellä, ja katolla oli noin kolmetuhatta miestä ja naista katselemassa, kuinka Simson heitä huvitti.',
        28: 'Simson huusi Herraa ja sanoi: "Herra, Herra, muista minua ja vahvista minua ainoastaan tämä kerta, oi Jumala, että saisin filistealaisille yhdellä kertaa kostetuksi molemmat silmäni!"',
        29: 'Simson kiersi käsivartensa molempien keskipylväiden ympäri, joiden varassa rakennus oli, toisen ympäri oikean ja toisen ympäri vasemman käsivartensa, ja painautui niitä vastaan.',
        30: 'Simson sanoi: "Menköön oma henkeni yhdessä filistealaisten kanssa!" Sitten hän taivuttautui eteenpäin niin rajusti, että rakennus luhistui ruhtinaiden ja kaiken siinä olevan kansan päälle. Kuolleita, jotka hän surmasi kuollessaan, oli enemmän kuin niitä, jotka hän oli surmannut eläessään.',
        31: 'Hänen veljensä ja koko hänen isänsä perhe menivät, ottivat hänet, veivät ja hautasivat hänet Soran ja Estaolin välille, hänen isänsä Maanoahin hautaan. Hän oli ollut tuomarina Israelissa kaksikymmentä vuotta.',
    },
    17: {
        1: 'Efraimin vuoristossa oli mies, nimeltä Miika.',
        2: 'Hän sanoi äidilleen: "Ne tuhatsata hopeasekeliä, jotka sinulta otettiin ja joiden tähden sinä lausuit vannotuksen minunkin kuulteni, katso, rahat ovat minulla. Minä ne otin." Silloin hänen äitinsä sanoi: " Herra siunatkoon sinua, poikani!"',
        3: 'Hän palautti äidilleen tuhatsata hopeasekeliä. Mutta hänen äitinsä sanoi: "Minä pyhitän nämä rahat Herralle ja luovutan ne pojalleni veistetyn ja valetun jumalankuvan teettämistä varten. Nyt annan ne sinulle takaisin."',
        4: 'Mutta hän antoi rahat takaisin äidilleen. Hänen äitinsä otti kaksisataa hopeasekeliä ja antoi ne kultasepälle, joka teki niistä veistetyn ja valetun jumalankuvan. Se oli sitten Miikan talossa.',
        5: 'Miehellä, Miikalla, oli jumalanhuone, ja hän teetti papinpuvun ja kotijumalien kuvia ja asetti yhden pojistaan itselleen papiksi.',
        6: 'Siihen aikaan ei ollut kuningasta Israelissa, ja jokainen teki sitä, mikä hänen omasta mielestään oli oikein.',
        7: 'Juudan Beetlehemissä oli nuori mies, Juudan sukukuntaa. Hän oli leeviläinen ja asui siellä muukalaisena.',
        8: 'Mies lähti siitä kaupungista, Juudan Beetlehemistä, asuakseen muukalaisena, missä vain sopisi, ja vaeltaessaan tietään hän tuli Efraimin vuoristoon, Miikan talolle.',
        9: 'Miika kysyi häneltä: "Mistä tulet?" Hän vastasi: "Minä olen leeviläinen Juudan Beetlehemistä ja vaellan asuakseni muukalaisena, missä vain sopii."',
        10: 'Miika sanoi hänelle: "Asetu luokseni ja tule isäkseni ja papikseni, niin minä annan sinulle vuosittain kymmenen hopeasekeliä, vaatetuksen ja elatuksesi." Leeviläinen tuli.',
        11: 'Leeviläinen suostui asettumaan miehen luo, ja tämä piti nuorta miestä kuin omaa poikaansa.',
        12: 'Miika asetti leeviläisen virkaan, ja nuoresta miehestä tuli hänen pappinsa, ja hän jäi Miikan taloon.',
        13: 'Miika sanoi: "Nyt tiedän, että Herra tekee minulle hyvää, sillä minulla on pappina leeviläinen."',
    },
    18: {
        1: 'Siihen aikaan ei ollut kuningasta Israelissa, ja siihen aikaan daanilaisten sukukunta etsi itselleen perintöosaa asuttavakseen, sillä siihen päivään asti se ei ollut saanut perintöosaa Israelin sukukuntien keskuudesta.',
        2: 'Daanilaiset lähettivät sukukuntansa keskuudesta viisi miestä, sotakuntoisia miehiä Sorasta ja Estaolista, vakoilemaan maata ja tutkimaan sitä. He sanoivat heille: "Menkää tutkimaan maata." Nämä tulivat Efraimin vuoristoon, Miikan talolle, ja yöpyivät sinne.',
        3: 'Ollessaan Miikan talon luona he tunsivat nuoren miehen hänen äänestään leeviläiseksi. He poikkesivat sinne ja kysyivät häneltä: "Kuka on tuonut sinut tänne? Mitä sinä täällä toimitat, ja mitä sinulla on täällä tekemistä?"',
        4: 'Hän vastasi heille: "Niin ja niin teki Miika minulle ja palkkasi minut papikseen."',
        5: 'He sanoivat hänelle: "Kysy Jumalalta, että saisimme tietää, onnistuuko matka, jolla olemme."',
        6: 'Pappi vastasi heille: "Menkää rauhassa. Matka, jolla olette, tapahtuu Herran edessä."',
        7: 'Nuo viisi miestä jatkoivat matkaansa ja tulivat Laikseen ja näkivät, että sikäläinen kansa asui huoleti siidonilaisten tavoin, rauhassa ja turvassa, eikä kukaan tehnyt vahinkoa tässä maassa rikkauksia anastamalla. He olivat myös etäällä siidonilaisista eivätkä olleet tekemisissä muiden ihmisten kanssa.',
        8: 'He tulivat veljiensä luo Soraan ja Estaoliin, ja heidän veljensä kysyivät heiltä: "Mitä kuuluu?"',
        9: 'He sanoivat: "Nouskaa, lähtekäämme heitä vastaan. Sillä olemme katselleet maata, ja katso, se on oikein hyvä. Tekö jäisitte toimettomiksi! Älkää vitkastelko, lähtekää liikkeelle, menkää sinne ja ottakaa maa omaksenne.',
        10: 'Kun tulette sinne, tulette huolettomana elävän kansan luo, ja maassa on tilaa joka suuntaan. Niin, Jumala antaa teidän käsiinne paikan, jossa ei ole puutetta mistään, mitä maan päällä on."',
        11: 'Niin sieltä, daanilaisten sukukunnasta, Sorasta ja Estaolista, lähti liikkeelle kuusisataa sota-asein varustettua miestä.',
        12: 'He nousivat Juudan Kirjat-Jearimiin ja leiriytyivät sinne. Sen tähden paikkaa kutsutaan vielä tänäkin päivänä "Daanin leiriksi". Se on Kirjat-Jearimin takana.',
        13: 'Sieltä he kulkivat Efraimin vuoristoon ja tulivat Miikan talolle.',
        14: 'Nuo viisi miestä, jotka olivat käyneet vakoilemassa Laiksen maata, rupesivat puhumaan ja sanoivat veljilleen: "Tiedättekö, että noissa huoneissa on kasukka ja kotijumalia sekä veistetty ja valettu jumalankuva? Miettikää siis, mitä teidän on tehtävä."',
        15: 'He poikkesivat sinne ja tulivat nuoren leeviläisen miehen asunnolle Miikan taloon ja tervehtivät häntä.',
        16: 'Ne kuusisataa sota-asein varustettua daanilaista asettuivat portin oven eteen.',
        17: 'Mutta nuo viisi miestä, jotka olivat käyneet vakoilemassa maata, nousivat taloon, menivät sisään ja ottivat veistetyn jumalankuvan, kasukan, kotijumalat ja valetun jumalankuvan, kun taas pappi ja ne kuusisataa sota-asein varustettua miestä seisoivat portin oven edessä.',
        18: 'Kun he menivät Miikan taloon ja ottivat veistetyn jumalankuvan, kasukan, kotijumalat ja valetun jumalankuvan, pappi kysyi heiltä: "Mitä te teette?"',
        19: 'He vastasivat hänelle: "Vaikene, pidä suusi kiinni ja lähde kanssamme ja tule isäksemme ja papiksemme. Onko sinun parempi olla pappina yhden miehen talossa kuin Israelin heimon ja sukukunnan pappina?"',
        20: 'Silloin pappi tuli hyville mielin ja otti kasukan, kotijumalat ja veistetyn jumalankuvan ja meni väkijoukkoon.',
        21: 'He kääntyivät jatkamaan matkaansa ja panivat vaimot ja lapset sekä karjan ja kuormaston kulkemaan edellään.',
        22: 'He olivat ehtineet vähän matkaa Miikan talosta, kun Miikan talon lähitalojen miehet kutsuttiin koolle, ja he pääsivät daanilaisten kintereille.',
        23: 'He huusivat daanilaisille. Nämä kääntyivät ja kysyivät Miikalta: "Mikä sinun on, kun väkesi on noin kutsuttu koolle?"',
        24: 'Hän vastasi: "Te olette vieneet jumalani, jotka olen teettänyt, ja papin, ja menette matkoihinne. Mitä minulla on enää jäljellä? Kuinka te vielä kysytte minulta: \'Mikä sinun on\'?"',
        25: 'Mutta daanilaiset sanoivat hänelle: "Lakkaa huutamasta meille, muuten miehet ärtyvät ja käyvät kimppuunne, ja menetätte henkenne, sekä sinä että perheesi."',
        26: 'Daanilaiset jatkoivat matkaansa, ja kun Miika näki, että he olivat häntä voimakkaammat, hän kääntyi ja palasi kotiinsa.',
        27: 'Otettuaan siis sen, minkä Miika oli teettänyt, sekä hänen pappinsa, he tulivat Laikseen rauhassa ja huolettomina elävän kansan kimppuun ja surmasivat heidät miekan terällä ja polttivat kaupungin tulella.',
        28: 'Eikä kukaan tullut avuksi, sillä se oli kaukana Siidonista eivätkä he olleet tekemisissä muitten ihmisten kanssa. Se oli Beet-Rehobin tasangolla. Daanilaiset rakensivat kaupungin uudestaan ja asettuivat siihen.',
        29: 'He antoivat kaupungille nimen Daan, isänsä Daanin nimen mukaan, hänen, joka oli Israelille syntynyt. Mutta ennen kaupungin nimi oli ollut Lais.',
        30: 'Sitten daanilaiset pystyttivät itselleen tuon veistetyn jumalankuvan. Joonatan, Manassen pojan Geersomin poika, ja hänen poikansa olivat daanilaisten sukukunnan pappeina, kunnes maan väestö vietiin karkotukseen.',
        31: 'He pystyttivät itselleen sen veistetyn jumalankuvan, jonka Miika oli teettänyt, ja se oli siellä koko sen ajan, minkä Jumalan huone oli Siilossa.',
    },
    19: {
        1: 'Siihen aikaan, kun Israelissa ei ollut kuningasta, eräs leeviläinen mies asui muukalaisena Efraimin vuoriston perukoilla ja otti itselleen sivuvaimon Juudan Beetlehemistä.',
        2: 'Mutta hänen sivuvaimonsa oli hänelle uskoton ja meni hänen luotaan isänsä kotiin Juudan Beetlehemiin, ja hän oli siellä jonkin aikaa, neljä kuukautta.',
        3: 'Sitten hänen miehensä nousi ja lähti hänen jälkeensä puhuakseen hänelle mieliksi ja palauttaakseen hänet luokseen. Hänellä oli mukanaan palvelija ja aasipari. Nainen vei hänet isänsä kotiin, ja kun naisen isä näki hänet, hän riensi iloisena häntä vastaan.',
        4: 'Hänen appensa, naisen isä, pidätteli häntä, niin että hän viipyi hänen luonaan kolme päivää. He söivät ja joivat ja olivat siellä yötä.',
        5: 'Neljäntenä päivänä hän varhain aamulla nousi lähteäkseen, mutta naisen isä sanoi vävylleen: "Vahvista itseäsi leipäpalalla. Sitten saatte lähteä."',
        6: 'He istuivat, söivät ja joivat molemmat yhdessä. Sitten naisen isä sanoi miehelle: "Suostu jäämään yöksi, ja olkoon sydämesi iloinen."',
        7: 'Mies nousi lähteäkseen. Silloin hänen appensa pyysi häntä pyytämällä, ja hän jäi sinne vielä yöksi.',
        8: 'Viidentenä päivänä hän varhain aamulla nousi lähteäkseen, mutta naisen isä sanoi hänelle: "Vahvista itseäsi, ja viipykää iltapäivään asti." He söivät toistensa kanssa.',
        9: 'Mies nousi lähteäkseen sivuvaimonsa ja palvelijansa kanssa, mutta hänen appensa, naisen isä, sanoi hänelle: "Katso, päivä kallistuu iltaan, jääkää yöksi, päivä on menemässä mailleen, jää tänne yöksi, ja olkoon sydämesi iloinen. Nouskaa huomenna varhain matkallenne, ja lähde sitten majallesi."',
        10: 'Mutta mies ei tahtonut jäädä yöksi, vaan nousi ja lähti ja tuli Jebuksen, se on Jerusalemin, kohdalle, mukanaan satuloitu aasipari ja sivuvaimonsa.',
        11: 'Kun he olivat Jebuksen luona ja päivä oli kohta laskemassa, palvelija sanoi isännälleen: "Tule, poiketkaamme tuohon jebusilaisten kaupunkiin ja yöpykäämme siellä."',
        12: 'Mutta hänen isäntänsä vastasi hänelle: "Emme poikkea vieraiden kaupunkiin, jotka eivät ole israelilaisia, vaan menemme edelleen Gibeaan asti."',
        13: 'Hän sanoi palvelijalleen: "Tule, pyrkikäämme toiseen paikkaan, yöpykäämme Gibeassa tai Raamassa."',
        14: 'He jatkoivat matkaansa, ja aurinko laski heiltä lähellä Gibeaa, joka on Benjaminissa.',
        15: 'He poikkesivat Gibeaan yöpyäkseen siellä. Hän tuli sinne ja istuutui kaupungin torille, mutta kukaan ei ottanut heitä yöksi huoneeseen.',
        16: 'Mutta katso, illalla tuli vanha mies työstään kedolta. Hän oli Efraimin vuoristosta ja asui muukalaisena Gibeassa. Mutta paikkakunnan miehet olivat benjaminilaisia.',
        17: 'Kun hän nosti silmänsä, hän näki matkamiehen kaupungin torilla. Silloin vanha mies sanoi: "Minne olet matkalla ja mistä tulet?"',
        18: 'Hän vastasi hänelle sanoen: "Olemme matkalla Juudan Beetlehemistä Efraimin vuoriston perukoille. Sieltä olen kotoisin ja olen käynyt Juudan Beetlehemissä asti. Olen matkalla Herran huoneeseen, mutta kukaan ei ota minua sisälle taloonsa.',
        19: 'Meillä on sekä olkia että muuta rehua aaseillemme, niin myös leipää ja viiniä minulle itselleni ja palvelijattarellesi ja nuorelle miehelle, joka on palvelijasi kanssa, niin ettei meiltä puutu mitään."',
        20: 'Vanha mies sanoi: "Rauha sinulle! Minun asiani on, jos sinulta jotakin puuttuisi. Älä vain jää yöksi tähän torille."',
        21: 'Sitten hän vei hänet taloonsa ja teki aaseille appeen. He pesivät jalkansa ja söivät ja joivat.',
        22: 'Kun he olivat ilahduttamassa sydäntään, katso, kaupungin miehet, kelvottomat miehet, piirittivät talon, kolkuttivat ovelle ja sanoivat vanhalle miehelle, talon isännälle, näin: "Tuo tänne se mies, joka tuli taloosi, yhtyäksemme häneen."',
        23: 'Mutta mies, talon isäntä, meni ulos heidän luokseen ja sanoi heille: "Älkää, veljeni, älkää tehkö niin pahoin! Kun kerran tämä mies on tullut minun talooni, älkää tehkö sellaista häpeällistä tekoa.',
        24: 'Katso, täällä on tyttäreni, joka on neitsyt, ja tämän miehen sivuvaimo. Minä tuon heidät tänne. Tehkää heille väkivaltaa, tehkää heille, mitä tahdotte, mutta tälle miehelle älkää tehkö sellaista häpeällistä tekoa."',
        25: 'Mutta miehet eivät tahtoneet häntä kuulla. Silloin mies tarttui sivuvaimoonsa ja vei hänet heidän luokseen kadulle, ja he yhtyivät häneen ja pitelivät häntä pahoin koko yön aina aamuun asti, ja vasta aamun sarastaessa he hänet päästivät.',
        26: 'Päivän koittaessa vaimo tuli ja kaatui [kuolleena] sen miehen talon oven eteen, jonka talossa hänen isäntänsä oli, ja makasi siinä, kunnes päivä valkeni.',
        27: 'Kun hänen isäntänsä aamulla nousi ja avasi talon oven ja tuli ulos lähteäkseen matkalle, katso, hänen sivuvaimonsa makasi talon oven edessä, kädet kynnyksellä.',
        28: 'Hän sanoi hänelle: "Nouse ja lähtekäämme!" Mutta vastausta ei tullut. Silloin mies nosti hänet aasin selkään, nousi ja lähti kotiinsa.',
        29: 'Mutta kotiin tultuaan hän otti veitsen, tarttui sivuvaimoonsa, paloitteli hänet luineen kaikkineen kahdeksitoista kappaleeksi ja lähetti ne kaikkialle Israelin alueelle.',
        30: 'Jokainen, joka sen näki, sanoi: "Mitään sellaista ei ole tapahtunut eikä nähty siitä päivästä lähtien, jona israelilaiset tulivat Egyptin maasta, aina tähän päivään saakka. Harkitkaa tätä, neuvotelkaa ja puhukaa."',
    },
    20: {
        1: 'Kaikki israelilaiset lähtivät liikkeelle, ja kansa kokoontui yhtenä miehenä Daanista aina Beersebaan saakka, niin myös Gileadin maasta, Herran eteen Mispaan.',
        2: 'Koko kansan päämiehet ja kaikki Israelin sukukunnat astuivat esiin Jumalan kansan seurakunnassa: neljäsataa tuhatta miekalla varustettua jalkamiestä.',
        3: 'Benjaminilaiset saivat kuulla, että israelilaiset olivat menneet Mispaan. Israelilaiset sanoivat: "Kertokaa, kuinka tämä ilkityö tapahtui."',
        4: 'Niin leeviläinen mies, murhatun vaimon mies, vastasi ja sanoi: "Minä ja minun sivuvaimoni olimme tulleet Benjaminin Gibeaan yöpyäksemme sinne.',
        5: 'Silloin Gibean miehet nousivat minua vastaan ja piirittivät yöllä talon, jossa olin. Minut he aikoivat tappaa ja sivuvaimolleni he tekivät väkivaltaa, niin että hän kuoli.',
        6: 'Sitten tartuin sivuvaimooni ja paloittelin hänet ja lähetin kappaleet kaikkialle Israelin perintömaahan, koska he olivat tehneet ilkityön ja häpeällisen teon Israelissa.',
        7: 'Katso, te israelilaiset, te olette nyt tässä kaikki. Keskustelkaa ja neuvotelkaa tässä paikassa."',
        8: 'Silloin nousi kaikki kansa yhtenä miehenä ja sanoi: "Älköön meistä kukaan menkö teltalleen, älköön kukaan poistuko kotiinsa.',
        9: 'Tämän me nyt teemme Gibealle: menemme sitä vastaan arvan mukaan.',
        10: 'Me otamme kymmenen miestä sadasta, Israelin kaikista sukukunnista, ja sata tuhannesta ja tuhat kymmenestätuhannesta, hankkimaan muonaa kansalle, kun se menee kostamaan Benjaminin Gibealle sen häpeällisen teon, minkä se on tehnyt Israelissa."',
        11: 'Niin kokoontuivat kaikki Israelin miehet kaupunkia vastaan kuin yhdeksi mieheksi yhtyneinä.',
        12: 'Israelin sukukunnat lähettivät miehiä kaikkiin Benjaminin sukuihin sanomaan: "Millainen rikos onkaan tehty teidän keskuudessanne!',
        13: 'Luovuttakaa nyt ne Gibean kelvottomat miehet, surmataksemme heidät ja poistaaksemme pahan Israelista." Mutta benjaminilaiset eivät tahtoneet kuulla veljiään, israelilaisia.',
        14: 'Benjaminilaiset kokoontuivat kaupungeistaan Gibeaan lähteäkseen sotaan israelilaisia vastaan.',
        15: 'Sinä päivänä pidettiin benjaminilaisten katselmus. Heitä oli muista kaupungeista kaksikymmentäkuusi tuhatta miekkamiestä, ottamatta lukuun Gibean asukkaita, joita katselmuksessa oli seitsemänsataa valiomiestä.',
        16: 'Kaikesta tästä väestä oli seitsemänsataa valiomiestä vasenkätistä. Jokainen näistä osasi lingota kiven hiuskarvalleen, erehtymättä.',
        17: 'Myös pidettiin Israelin miesten katselmus, ja heitä oli, paitsi benjaminilaisia, neljäsataa tuhatta miekkamiestä, kaikki sotilaita.',
        18: 'He nousivat ja lähtivät Beeteliin ja kysyivät Jumalalta. Israelilaiset sanoivat: "Kenen meistä on ensiksi lähdettävä taistelemaan benjaminilaisia vastaan?" Herra vastasi: "Juuda ensiksi."',
        19: 'Israelilaiset lähtivät liikkeelle seuraavana aamuna ja asettuivat leiriin Gibean edustalle.',
        20: 'Israelin miehet lähtivät taistelemaan Benjaminia vastaan, ja Israelin miehet asettuivat sotarintaan heitä vastaan Gibean edustalle.',
        21: 'Mutta benjaminilaiset ryntäsivät ulos Gibeasta ja kaatoivat sinä päivänä Israelista kaksikymmentäkaksi tuhatta miestä.',
        22: 'Mutta kansa, Israelin miehet, rohkaisivat mielensä ja asettuivat jälleen rintamaan samalle paikalle, mihin olivat asettuneet ensimmäisenä päivänä.',
        23: 'Sillä kun israelilaiset menivät ja itkivät Herran edessä iltaan asti ja kysyivät Herralta sanoen: "Onko minun vielä ryhdyttävä taisteluun veljiäni, benjaminilaisia, vastaan?" Herra vastasi: "Menkää heitä vastaan."',
        24: 'Toisena päivänä israelilaiset lähenivät benjaminilaisia.',
        25: 'Benjaminilaiset toisena päivänä ryntäsivät Gibeasta heitä vastaan ja kaatoivat israelilaisia vielä kahdeksantoista tuhatta miestä, kaikki miekkamiehiä.',
        26: 'Silloin kaikki israelilaiset, koko kansa, lähtivät ja tulivat Beeteliin ja itkivät ja istuivat siellä Herran edessä ja paastosivat sen päivän aina iltaan asti. He uhrasivat polttouhreja ja rauhanuhreja Herran edessä.',
        27: 'Israelilaiset kysyivät Herralta – sillä Jumalan liitonarkki oli siihen aikaan siellä,',
        28: 'ja Piinehas, Aaronin pojan Eleasarin poika, seisoi siihen aikaan sen edessä – ja sanoivat: "Onko minun vielä lähdettävä taisteluun veljiäni, benjaminilaisia, vastaan, vai onko minun siitä luovuttava?" Herra vastasi: "Lähtekää, sillä huomenna minä annan heidät sinun käsiisi."',
        29: 'Silloin Israel asetti väijytyksiä Gibean ympärille,',
        30: 'ja israelilaiset menivät kolmantena päivänä benjaminilaisia vastaan ja asettuivat rintamaan Gibeaa vastaan niin kuin edellisilläkin kerroilla.',
        31: 'Benjaminilaiset ryntäsivät ulos kansaa vastaan, mutta tulivat eristetyiksi kaupungista. Kuten edellisilläkin kerroilla he aluksi saivat lyödyksi kansaa kuoliaaksi niillä valtateillä, joista toinen vie Beeteliin, toinen kedon yli Gibeaan, noin kolmekymmentä Israelin miestä.',
        32: 'Silloin benjaminilaiset sanoivat: "Me voitimme heidät nyt niin kuin ennenkin." Mutta israelilaiset sanoivat: "Paetkaamme ja eristäkäämme heidät kaupungista valtateille."',
        33: 'Kaikki Israelin miehet nousivat kukin paikaltaan ja asettuivat rintamaan Baal-Taamariin, ja väijyksissä oleva Israelin joukko syöksyi esiin paikaltaan Geban aukealta.',
        34: 'Niin tuli kymmenentuhatta valiomiestä koko Israelista Gibean edustalle, ja syntyi ankara taistelu, eivätkä he huomanneet, että onnettomuus oli kohtaamassa heitä.',
        35: 'Herra antoi Israelin voittaa Benjaminin, ja israelilaiset kaatoivat sinä päivänä Benjaminista kaksikymmentäviisi tuhatta ja sata miestä, kaikki miekkamiehiä.',
        36: 'Nyt benjaminilaiset näkivät olevansa voitetut. Mutta Israelin miehet väistyivät benjaminilaisten tieltä, sillä he luottivat väijytykseen, jonka olivat asettaneet Gibeaa vastaan.',
        37: 'Silloin väijyksissä ollut joukko riensi ja karkasi Gibeaan. Väijyksissä ollut joukko meni ja surmasi kaikki kaupungin asukkaat miekan terällä.',
        38: 'Israelin miehet olivat sopineet väijyksissä olevan joukon kanssa, että se panisi sakean savupilven nousemaan kaupungista.',
        39: 'Kun siis Israelin miehet olivat kääntyneet pakoon taistelussa, ja kun Benjaminin miehet aluksi olivat lyöneet kuoliaaksi Israelin miehiä noin kolmekymmentä miestä ja sanoneet: "Varmasti me voitamme heidät niin kuin ensimmäisessäkin taistelussa",',
        40: 'niin alkoi pilvi, savupatsas, nousta kaupungista. Kun benjaminilaiset kääntyivät taaksepäin, katso, koko kaupunki nousi savuna taivasta kohti.',
        41: 'Israelin miehet kääntyivät takaisin, mutta Benjaminin miehet kauhistuivat, sillä he näkivät, että onnettomuus oli kohdannut heitä.',
        42: 'He kääntyivät pakoon Israelin miesten edestä erämaan tielle, mutta sota seurasi heitä heidän kintereillään. Sikäläisten kaupunkien asukkaat kaatoivat heitä heidän keskeltään.',
        43: 'He saartoivat Benjaminin, ajoivat heitä takaa ja tallasivat heitä maahan levähdyspaikassa ja aina Gibean kohdalle asti auringonnousuun päin.',
        44: 'Niin kaatui Benjaminista kahdeksantoistatuhatta miestä, kaikki sotakuntoisia miehiä.',
        45: 'He kääntyivät ja pakenivat erämaahan päin Rimmonin kalliolle. Israelilaiset tekivät heistä valtateillä vielä jälkikorjuun, surmaten viisituhatta miestä, ja seurasivat heitä heidän kintereillään aina Gideomiin asti ja surmasivat heitä kaksituhatta miestä.',
        46: 'Kaikkiaan oli niitä, jotka sinä päivänä kaatuivat Benjaminista, kaksikymmentäviisi tuhatta miekkamiestä, kaikki sotakuntoisia miehiä.',
        47: 'Heitä kääntyi pakoon kohti erämaata, Rimmonin kalliolle, kuusisataa miestä. He jäivät Rimmonin kalliolle neljäksi kuukaudeksi.',
        48: 'Mutta Israelin miehet palasivat takaisin benjaminilaisten luo ja surmasivat heidät miekan terällä, [tuhosivat] kaupungin sekä vahingoittumatta jääneet ihmiset että eläimet, kaiken, minkä tapasivat. Myös he pistivät tuleen kaikki kaupungit, joihin tulivat.',
    },
    21: {
        1: 'Israelin miehet olivat vannoneet Mispassa ja sanoneet: "Kukaan meistä ei anna tytärtään benjaminilaiselle vaimoksi."',
        2: 'Kansa oli tullut Beeteliin, ja he istuivat siellä aina iltaan asti Jumalan edessä, korottivat äänensä ja itkivät katkerasti',
        3: 'ja sanoivat: "Miksi, oi Herra, Israelin Jumala, Israelissa on käynyt niin, että Israelista puuttuu nyt yksi sukukunta?"',
        4: 'Varhain seuraavana päivänä kansa nousi ja rakensi sinne alttarin ja uhrasi polttouhreja ja rauhanuhreja.',
        5: 'Israelilaiset sanoivat: "Onko yhdessäkään Israelin sukukunnassa ketään, joka ei ole tullut seurakunnan kanssa tänne Herran eteen?" Sillä siitä, joka ei tulisi Herran luo Mispaan, oli vannottu ankara vala: "Hänet on kuolemalla rangaistava."',
        6: 'Israelilaisten tuli sääli veljeään Benjaminia, ja he sanoivat: "Tänä päivänä yksi sukukunta on hakattu pois Israelista.',
        7: 'Mitä meidän on tehtävä, että jäljelle jääneet saavat vaimoja? Sillä itse me olemme vannoneet Herran kautta, ettemme anna heille tyttäriämme vaimoiksi."',
        8: 'He kysyivät: "Onko Israelin sukukunnissa ainoatakaan, joka ei ollut tullut Herran eteen Mispaan?" Niin, katso, Gileadin Jaabeksesta ei ollut ketään tullut leiriin, seurakuntakokoukseen.',
        9: 'Sillä kun kansasta pidettiin katselmus, katso, siellä ei ollut ketään Gileadin Jaabeksen asukkaista.',
        10: 'Kansa lähetti sinne kaksitoista tuhatta sotakuntoista miestä ja käski heitä sanoen: "Menkää ja surmatkaa miekan terällä Gileadin Jaabeksen asukkaat vaimoineen ja lapsineen.',
        11: 'Tehkää näin: kaikki miespuoliset ja kaikki naiset, jotka ovat yhtyneet mieheen, vihkikää tuhon omiksi."',
        12: 'Mutta Gileadin Jaabeksen asukkaista he löysivät neljäsataa nuorta naista, jotka olivat neitsyitä eivätkä olleet yhtyneet mieheen. He veivät nämä leiriin Siiloon, joka on Kanaanin maassa.',
        13: 'Sitten koko kansa lähetti sanansaattajia puhumaan benjaminilaisten kanssa, jotka olivat Rimmonin kalliolla, ja tarjosi heille rauhaa.',
        14: 'Silloin benjaminilaiset palasivat takaisin, ja heille annettiin ne naiset, jotka oli jätetty henkiin Gileadin Jaabeksen naisista. Mutta ne eivät riittäneet heille.',
        15: 'Kansan tuli sääli Benjaminia, koska Herra oli tehnyt aukon Israelin sukukuntiin.',
        16: 'Silloin kansan vanhimmat sanoivat: "Mitä meidän on tehtävä, että jäljelle jääneet saisivat vaimoja? Sillä onhan naiset hävitetty Benjaminista."',
        17: 'He sanoivat: "Pelastuneiden perintöomaisuus on jäävä Benjaminille, ettei yksikään sukukunta häviäisi Israelista.',
        18: 'Mutta itse emme voi antaa heille tyttäriämme vaimoiksi, sillä israelilaiset ovat vannoneet ja sanoneet: kirottu olkoon se, joka antaa vaimon benjaminilaiselle."',
        19: 'He sanoivat: "Katso, joka vuosi vietetään Herran juhla Siilossa, joka on pohjoiseen Beetelistä, auringonnousun suuntaan siitä valtatiestä, joka vie Beetelistä Sikemiin, ja etelään Lebonasta."',
        20: 'He käskivät benjaminilaisia sanoen: "Menkää ja asettukaa väijyksiin viinitarhoihin.',
        21: 'Kun näette Siilon tyttärien tulevan ulos karkeloimaan, rynnätkää viinitarhoista ja ryöstäkää jokainen itsellenne vaimo Siilon tyttäristä ja lähtekää Benjaminin maahan.',
        22: 'Kun heidän isänsä tai veljensä tulevat valittamaan meille, sanomme heille: \'Lahjoittakaa heidät meille, sillä ei kukaan meistä ole ottanut sodalla vaimoa. Ettehän te ole itse antaneet niitä heille, muuten olisitte joutuneet syyllisiksi.\'"',
        23: 'Benjaminilaiset tekivät niin ja ottivat lukumääränsä mukaan itselleen vaimoja karkeloivien joukosta ryöstäen heidät. Sitten he palasivat perintöosaansa ja rakensivat uudestaan kaupungit ja asettuivat niihin.',
        24: 'Silloin israelilaisetkin vaelsivat sieltä, kukin sukukuntaansa ja sukuunsa, ja menivät sieltä kukin perintöosalleen.',
        25: 'Siihen aikaan ei ollut kuningasta Israelissa. Jokainen teki sitä, mikä hänen omasta mielestään oli oikein.',
    },
}
